import React, { useState, useEffect } from "react";
import {
  applySuggestedFix,
  checkMyWorld,
  fixMyWorld,
  REPAIR_CENTS,
  VALIDATOR_FIX_CENTS,
  checkWorld,
  deleteWorld,
  generateCompleteWalkthrough,
  isFullyIllustrated,
  loadArt,
  loadSuggestedFixData,
  loadSetting,
  loadSuggestedFixStatus,
  loadWorldData,
  money,
  saveEndingText,
  writeEndingDraft,
  repairWorld,
  revertToBackup,
  saveWorldData,
  sendSuggestedFix,
  saveWorldDetails,
  setPublished,
  summarizeWorldDiff,
  syncArtEntries,
  withdrawSuggestedFix,
} from "../lib/db";
import { buildWalkthrough } from "../engine/engine";
import { ArtTab } from "./ArtTab";
import { T, inputStyle } from "../theme";
import { Btn, Chip, Empty, Field } from "../ui/primitives";
import { renderMarkdown } from "../ui/markdownLite";

export function EditGame({ game, refreshWorlds, me, setMe, go, chars, initialTab }) {
  const [tab, setTab] = useState(initialTab ?? "art");
  const [art, setArt] = useState(null);
  const [illustrated, setIllustrated] = useState(false);
  const [pubError, setPubError] = useState(null);
  const [deleteStage, setDeleteStage] = useState(0);      // 0 idle | 1 confirming | 2 typing the name
  const [deleteText, setDeleteText] = useState("");
  const [deleting, setDeleting] = useState(false);

  const checkIllustrated = () => {
    if (!game?.id) return;
    isFullyIllustrated(game.id).then(setIllustrated).catch(() => setIllustrated(false));
  };

  useEffect(() => {
    if (!game) return;
    let cancelled = false;
    loadArt(game.id)
      .then((rs) => { if (!cancelled) setArt(rs); })
      .catch(() => { if (!cancelled) setArt([]); });
    checkIllustrated();
    return () => { cancelled = true; };
  }, [game?.id]);

  if (!game) return <Empty title="Not found." line="This world may have been deleted." />;
  if (game.authorId !== me?.id && !me?.isAdmin) {
    return <Empty title="Not your world." line="You can only edit worlds you created." />;
  }

  // Someone else's game, seen by an admin: look, check, suggest. Only the
  // creator can change their own live game, so none of the owner's controls
  // (details, pictures, publish, delete, overwrite) are shown.
  const isOwner = game.authorId === me?.id;
  const reviewOnly = !isOwner && Boolean(me?.isAdmin);
  const tabs = reviewOnly
    ? [["repair", "Changes / Repairs"], ["walkthrough", "Walkthrough"], ["validator", "Validator"]]
    : [["details", "Details"], ["art", "Pictures"], ["walkthrough", "Walkthrough"], ["repair", "Changes / Repairs"], ["validator", "Validator"], ["settings", "Settings"]];
  const shownTab = tabs.some(([k]) => k === tab) ? tab : (reviewOnly ? "repair" : tab);

  return (
    <div className="pf-in">
      <Btn kind="ghost" onClick={() => go("game", { id: game.id, from: "mine" })}
        style={{ marginBottom: 14 }}>back</Btn>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 4, flexWrap: "wrap" }}>
        <h1 style={{ fontFamily: T.serif, fontSize: 28, fontWeight: 400, margin: 0 }}>
          <span role="link" tabIndex={0} title="Open this game's page"
            onClick={() => go("game", { id: game.id, from: "mine" })}
            onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); go("game", { id: game.id, from: "mine" }); } }}
            style={{ cursor: "pointer", color: "inherit", textDecoration: "none" }}>
            {game.title}
          </span>
        </h1>
        <Chip status={game.status} published={game.published} />
      </div>
      <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, marginBottom: 18 }}>
        {game.rooms} rooms &middot; {game.mobs} characters &middot; {game.plays.toLocaleString()} plays
      </div>

      {reviewOnly && (
        <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.ochre, lineHeight: 1.7,
          border: "1px solid " + T.ochre + "55", padding: "10px 14px", borderRadius: 2, margin: "0 0 18px" }}>
          You are looking at someone else's game as an admin. You can check it and suggest a fix;
          only its creator can change it.
        </p>
      )}

      {game.status === "ready" && (
        <div style={{ marginBottom: 22, display: "flex", alignItems: "center", gap: 10 }}>
          <Btn kind="solid" disabled={!chars?.length}
            onClick={() => go("play", { id: game.id, charId: chars?.[0]?.id, authorUsername: game.authorUsername, slug: game.slug })}>
            Play
          </Btn>
          <Btn kind="ghost" disabled={!chars?.length}
            title="The game plays itself from the start, typing the walkthrough's commands"
            style={{ border: "1px solid " + T.ochre, color: T.ochre, padding: "8px 14px", borderRadius: 2 }}
            onClick={() => {
              try { sessionStorage.setItem("ascentery_autoplay", String(game.id)); } catch { /* storage unavailable */ }
              go("play", { id: game.id, charId: chars?.[0]?.id, authorUsername: game.authorUsername, slug: game.slug });
            }}>
            Autoplay
          </Btn>
          {!chars?.length && (
            <span style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>
              Make a character on your profile first.
            </span>
          )}
          {!reviewOnly && <Btn kind={game.published ? "ghost" : (illustrated ? "solid" : "quiet")}
            disabled={!game.published && !illustrated}
            style={{ marginLeft: "auto", ...(game.published ? { borderColor: T.moss, color: T.moss } : {}) }}
            onClick={async () => {
              setPubError(null);
              try {
                await setPublished(game.id, !game.published);
                await refreshWorlds();
              } catch (e) {
                if (e.needsUsername) go("username", { reason: "publish", next: "mine" });
                else setPubError(e.message);
              }
            }}>
            {game.published ? "Unpublish" : "Publish"}
          </Btn>}
        </div>
      )}

      {game.status === "failed" && !reviewOnly && (
        <div style={{ marginBottom: 22 }}>
          {game.failureNote && (
            <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, lineHeight: 1.7,
              border: "1px solid " + T.clay + "44", padding: 14, borderRadius: 2, marginBottom: 14 }}>
              {game.failureNote}
            </p>
          )}
          <Btn kind="solid" onClick={() => go("create", { resumeId: game.id })}>
            Try building the world again
          </Btn>
        </div>
      )}

      <div style={{ display: "flex", gap: 4, borderBottom: "1px solid " + T.edge, marginBottom: 24, flexWrap: "wrap" }}>
        {tabs.map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)} className="pf-btn"
            style={{ background: "none", border: "none", cursor: "pointer", padding: "10px 14px", fontFamily: T.mono, fontSize: 12,
              color: shownTab === k ? T.bone : T.boneDim, boxShadow: shownTab === k ? "inset 0 -2px 0 " + T.ochre : "none" }}>
            {label}
          </button>
        ))}
      </div>

      {shownTab === "art" && (
        art === null
          ? <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>
          : <>
              {art.length
                ? <ArtTab entries={art} setEntries={setArt} me={me} setMe={setMe} worldId={game.id} onDrawn={checkIllustrated} title={game.title} />
                : <Empty title="Nothing to draw yet." line="Pictures appear once the world has been built." />
              }
            </>
      )}

      {shownTab === "details" && <DetailsTab game={game} refreshWorlds={refreshWorlds} />}

      {shownTab === "walkthrough" && (
        game.status === "ready"
          ? <WalkthroughTab worldId={game.id} me={me} setMe={setMe} go={go} />
          : <Empty title="Nothing to walk through yet." line="This world has not finished building." />
      )}

      {shownTab === "repair" && (
        game.status === "ready"
          ? <RepairTab worldId={game.id} title={game.title} isAdmin={me?.isAdmin}
              isOwner={isOwner} published={Boolean(game.published)}
              onJsonSaved={async () => {
              try {
                const added = await syncArtEntries(game.id);
                if (added > 0) {
                  const fresh = await loadArt(game.id);
                  setArt(fresh);
                }
              } catch {
                // sync failures are silent — the user saved the JSON successfully
              }
              try { await refreshWorlds?.(); } catch { /* catalogue counts refresh on next load */ }
            }} />
          : <Empty title="Nothing to repair yet." line="This world has not finished building." />
      )}

      {shownTab === "validator" && <ValidatorTab worldId={game.id} status={game.status} isOwner={isOwner} reviewOnly={reviewOnly} me={me} setMe={setMe}
        onFixed={async () => {
          try {
            const added = await syncArtEntries(game.id);
            if (added > 0) setArt(await loadArt(game.id));
          } catch { /* art slots sync again on the next visit */ }
          try { await refreshWorlds?.(); } catch { /* catalogue counts refresh on next load */ }
        }} />}

      {shownTab === "settings" && (
        <div style={{ maxWidth: 480 }}>
          <Field label="Published"
            hint={game.published
              ? "Unpublishing hides it from Browse. People mid-playthrough keep their saves."
              : illustrated
                ? "Every picture is drawn. Ready when you are."
                : "A world can be published once every room, character, item and prop has a picture. Check the Pictures tab."}>
            <Btn disabled={game.status !== "ready" || (!game.published && !illustrated)}
              onClick={async () => {
                setPubError(null);
                try {
                  await setPublished(game.id, !game.published);
                  await refreshWorlds();
                } catch (e) {
                  if (e.needsUsername) go("username", { reason: "publish", next: "mine" });
                  else setPubError(e.message);
                }
              }}>
              {game.published ? "Unpublish" : "Publish"}
            </Btn>
          </Field>
          {pubError && (
            <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginTop: -8, marginBottom: 18 }}>
              {pubError}
            </p>
          )}
          <div style={{ borderTop: "1px solid " + T.edge, paddingTop: 20, marginTop: 20 }}>
            {deleteStage === 0 && (
              <Btn kind="danger" onClick={() => setDeleteStage(1)}>
                Delete this world
              </Btn>
            )}

            {deleteStage === 1 && (
              <div>
                <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, lineHeight: 1.7, margin: "0 0 12px" }}>
                  This deletes "{game.title}" — every room, character, item, picture, and anyone's
                  save — for good. Are you sure?
                </p>
                <div style={{ display: "flex", gap: 10 }}>
                  <Btn kind="danger" onClick={() => setDeleteStage(2)}>Yes, delete it</Btn>
                  <Btn kind="ghost" onClick={() => setDeleteStage(0)}>Never mind</Btn>
                </div>
              </div>
            )}

            {deleteStage === 2 && (
              <div>
                <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay, lineHeight: 1.7, margin: "0 0 12px" }}>
                  Type the world's exact title to confirm — "{game.title}".
                </p>
                <input value={deleteText} onChange={(e) => setDeleteText(e.target.value)}
                  placeholder={game.title}
                  style={{ ...inputStyle, marginBottom: 12 }} />
                <div style={{ display: "flex", gap: 10 }}>
                  <Btn kind="danger" disabled={deleting || deleteText !== game.title}
                    onClick={async () => {
                      setDeleting(true);
                      try { await deleteWorld(game.id); await refreshWorlds(); go("mine"); }
                      catch (e) { console.error(e); setDeleting(false); }
                    }}>
                    {deleting ? "deleting…" : "Delete forever"}
                  </Btn>
                  <Btn kind="ghost" onClick={() => { setDeleteStage(0); setDeleteText(""); }}>Cancel</Btn>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export function DetailsTab({ game, refreshWorlds }) {
  const [title, setTitle] = useState(game.title);
  const [brief, setBrief] = useState(game.brief ?? "");
  const [saved, setSaved] = useState(false);
  const [error, setError] = useState(null);

  const save = async (patch) => {
    setError(null);
    try {
      await saveWorldDetails(game.id, patch);
      await refreshWorlds();
      setSaved(true);
      setTimeout(() => setSaved(false), 1600);
    } catch (e) {
      setError(e.message);
    }
  };

  return (
    <div style={{ maxWidth: 560 }}>
      <Field label="Title" hint="Shown on the catalog card and used to build the splash screen.">
        <input value={title} onChange={(e) => setTitle(e.target.value)}
          onBlur={() => save({ title })} style={inputStyle} />
      </Field>

      {/* The next three follow the Create wizard's own order — what was
          typed, what it became, what it became again — so reading down
          the page traces the same path building the world once did.
          Only the last one is still live; the first two are a historical
          record, kept purely so the story, goals, and tone don't get
          lost once the wizard that produced them is gone. Neither is
          shown at all for a world built before this was tracked. */}
      {game.gameBrief && (
        <Field label="The Game Brief" hint="What was originally typed into the first step of the Create wizard.">
          <textarea value={game.gameBrief} readOnly rows={6}
            style={{ ...inputStyle, lineHeight: 1.6, resize: "vertical", opacity: 0.75, cursor: "default" }} />
        </Field>
      )}

      {game.storyDetails && (
        <Field label="The Story Details" hint="What the brief above became after the wizard's second step expanded it.">
          <textarea value={game.storyDetails} readOnly rows={8}
            style={{ ...inputStyle, lineHeight: 1.6, resize: "vertical", opacity: 0.75, cursor: "default" }} />
        </Field>
      )}

      <Field label="The Game Details" hint="What actually went on to build the world. This is not shown to players, but it is what an amendment or repair reads for context.">
        <textarea value={brief} onChange={(e) => setBrief(e.target.value)}
          onBlur={() => save({ brief })} rows={10}
          style={{ ...inputStyle, lineHeight: 1.6, resize: "vertical" }} />
      </Field>

      <div style={{ fontFamily: T.mono, fontSize: 11, color: saved ? T.moss : T.clay, minHeight: 16 }}>
        {saved ? "saved" : error || " "}
      </div>
    </div>
  );
}

function WalkthroughTab({ worldId, me, setMe, go }) {
  const [world, setWorld] = useState(null);
  const [completeText, setCompleteText] = useState(null);
  const [error, setError] = useState(null);
  const [mode, setMode] = useState("compact");
  const [genBusy, setGenBusy] = useState(false);
  const [genError, setGenError] = useState(null);
  const [needsFunds, setNeedsFunds] = useState(false);
  const [copied, setCopied] = useState(false);
  const [regenBusy, setRegenBusy] = useState(false);
  const [regenError, setRegenError] = useState(null);
  const [regenKey, setRegenKey] = useState(0);

  useEffect(() => {
    let cancelled = false;
    loadWorldData(worldId)
      .then((d) => { if (!cancelled) { setWorld(d.data); setCompleteText(d.complete_walkthrough ?? null); } })
      .catch((e) => { if (!cancelled) setError(e.message); });
    return () => { cancelled = true; };
  }, [worldId]);

  const regenCompact = async () => {
    setRegenBusy(true); setRegenError(null);
    try {
      const d = await loadWorldData(worldId);
      setWorld(d.data);
      setRegenKey((k) => k + 1);
    } catch (e) {
      setRegenError(e.message);
    } finally {
      setRegenBusy(false);
    }
  };

  const generate = async () => {
    setGenBusy(true); setGenError(null); setNeedsFunds(false);
    try {
      const { text, balance_cents } = await generateCompleteWalkthrough(worldId);
      setCompleteText(text);
      if (typeof balance_cents === "number") setMe((m) => ({ ...m, balance: balance_cents }));
    } catch (e) {
      setGenError(e.message);
      setNeedsFunds(Boolean(e.needsFunds));
    } finally {
      setGenBusy(false);
    }
  };

  // Same fallback reasoning as copyJson in the Repair tab below: the
  // modern clipboard API is not universally available (older Safari,
  // some embedded webviews), and fails silently rather than throwing
  // something visible, so a classic textarea + execCommand fallback
  // covers far more of those cases.
  const copyWalkthrough = async () => {
    if (!completeText) return;
    try {
      await navigator.clipboard.writeText(completeText);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
      return;
    } catch { /* fall through to the classic approach below */ }

    try {
      const ta = document.createElement("textarea");
      ta.value = completeText;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      const ok = document.execCommand("copy");
      document.body.removeChild(ta);
      if (!ok) throw new Error("execCommand copy returned false");
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch {
      setGenError("Could not copy — your browser may be blocking clipboard access. Select the text above and copy it manually.");
    }
  };

  if (error) {
    return <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay }}>{error}</p>;
  }
  if (!world) {
    return <p style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>loading</p>;
  }

  const modeToggle = (
    <div style={{ display: "flex", gap: 6, marginBottom: 20 }}>
      {[["compact", "Compact Walkthrough"], ["complete", "Complete Walkthrough"]].map(([k, label]) => (
        <button key={k} onClick={() => setMode(k)} className="pf-btn"
          style={{ padding: "8px 14px", borderRadius: 2, cursor: "pointer", background: "transparent",
            fontFamily: T.mono, fontSize: 12, color: mode === k ? T.bone : T.boneDim,
            border: "1px solid " + (mode === k ? T.ochre : T.edge) }}>
          {label}
        </button>
      ))}
    </div>
  );

  if (mode === "complete") {
    return (
      <div style={{ maxWidth: 720 }}>
        {modeToggle}
        <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: "0 0 20px" }}>
          Written by a model, grounded in this world's actual rooms, characters, items, and quest
          stages — a narrative guide rather than a plain step list. Costs {money(8)} to write or rewrite,
          and is saved, not regenerated every time you open this tab.
        </p>

        <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: 18 }}>
          <Btn kind="solid" disabled={genBusy} onClick={generate}>
            {genBusy ? "writing…" : completeText ? `Rewrite · ${money(8)}` : `Write it · ${money(8)}`}
          </Btn>
          {completeText && (
            <Btn kind="ghost" style={{ marginLeft: "auto" }} onClick={copyWalkthrough}>
              {copied ? "Copied" : "Copy to clipboard"}
            </Btn>
          )}
        </div>

        {genError && (
          <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginBottom: 16 }}>
            {genError}
            {needsFunds && <Btn kind="ghost" style={{ marginLeft: 10 }} onClick={() => go("creator")}>Add funds</Btn>}
          </p>
        )}

        {completeText ? (
          <div style={{ background: T.raised, border: "1px solid " + T.edge, borderRadius: 4, padding: "8px 24px" }}>
            {renderMarkdown(completeText, {
              h1: { fontFamily: T.serif, fontSize: 24, color: T.bone, margin: "20px 0 10px" },
              h2: { fontFamily: T.serif, fontSize: 19, color: T.bone, margin: "18px 0 8px" },
              h3: { fontFamily: T.serif, fontSize: 16, color: T.ochre, margin: "14px 0 6px" },
              p: { fontFamily: T.serif, fontSize: 14.5, lineHeight: 1.7, color: T.bone, margin: "0 0 12px" },
              list: { margin: "0 0 14px", paddingLeft: 22 },
              listItem: { fontFamily: T.serif, fontSize: 14.5, lineHeight: 1.7, color: T.bone, marginBottom: 4 },
              blockquote: { fontFamily: T.serif, fontStyle: "italic", fontSize: 14.5, lineHeight: 1.7,
                color: T.boneDim, borderLeft: "3px solid " + T.edge, margin: "0 0 14px", padding: "2px 16px" },
              hr: { border: "none", borderTop: "1px solid " + T.edge, margin: "20px 0" },
              code: { fontFamily: T.mono, fontSize: 12.5, lineHeight: 1.5, color: T.boneDim,
                background: T.ground, border: "1px solid " + T.edge, borderRadius: 4,
                padding: "14px 16px", margin: "0 0 16px", overflowX: "auto", whiteSpace: "pre" },
              table: { fontFamily: T.mono, fontSize: 12 },
              th: { textAlign: "left", padding: "6px 10px", borderBottom: "1px solid " + T.ochre, color: T.ochre },
              td: { padding: "6px 10px", borderBottom: "1px solid " + T.edge, color: T.bone },
            })}
          </div>
        ) : !genBusy && (
          <Empty title="No complete walkthrough yet." line="Write one above to see it here." />
        )}
      </div>
    );
  }

  const steps = buildWalkthrough(world);
  if (!steps.length) {
    return (<div>{modeToggle}<Empty title="No quests in this world." line="There is nothing to walk through yet." /></div>);
  }

  const DIR_ARROW = { north: "↑", south: "↓", east: "→", west: "←", up: "↗", down: "↙" };

  return (
    <div style={{ maxWidth: 640 }}>
      {modeToggle}
      <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: "0 0 20px" }}>
        Computed directly from the world itself, the same way the reachability check is — not
        written by a model, so it cannot describe a step that does not actually work. If the world
        changes, so does this.
      </p>

      {steps.map((s, i) => (
        <div key={i} style={{ border: "1px solid " + T.edge, borderRadius: 2, padding: "12px 16px", marginBottom: 10 }}>
          <div style={{ fontFamily: T.mono, fontSize: 10.5, color: T.ochre, marginBottom: 4 }}>
            {s.quest}
          </div>
          <div style={{ fontFamily: T.serif, fontSize: 15.5, marginBottom: 8 }}>
            {i + 1}. {s.goal}
          </div>

          {(() => {
            const line = { fontFamily: T.mono, fontSize: 11.5, lineHeight: 1.9 };
            // Where to go next: the route the NEXT real step takes from the
            // room this one happens in. Nothing is shown when that step is in
            // the same room (there is still something to do here), or when
            // this is the last step.
            const here = !s.note && !s.already && s.room ? s.room : null;
            let go = null;
            if (here) {
              const nxt = steps.slice(i + 1).find((t) => !t.note && !t.already && t.room);
              if (nxt && nxt.room !== here && nxt.path.length) go = nxt.path;
            }
            if (s.already) {
              return (
                <div style={{ ...line, color: T.boneDim }}>
                  {s.roomName && <div>{"📍 "}{s.roomName}</div>}
                  <div>{"⚡ already done — "}{s.action}</div>
                </div>
              );
            }
            if (s.note) {
              return (
                <div style={{ ...line, color: T.clay }}>
                  {s.roomName && <div style={{ color: T.boneDim }}>{"📍 "}{s.roomName}</div>}
                  <div>{s.note}</div>
                </div>
              );
            }
            return (
              <div style={{ ...line, color: T.boneDim }}>
                <div>{"📍 "}{s.roomName}</div>
                <div>{"⚡ "}{s.action}</div>
                {go && <div>{"🚶 "}{go.map((d) => `${DIR_ARROW[d] ?? d} ${d}`).join("  ")}</div>}
              </div>
            );
          })()}
        </div>
      ))}

      {me?.isAdmin && (
        <div style={{ marginTop: 18, paddingTop: 18, borderTop: "1px solid " + T.edge }}>
          <Btn kind="ghost" disabled={regenBusy} onClick={regenCompact}>
            {regenBusy ? "reloading…" : "Recompute walkthrough"}
          </Btn>
          {regenError && (
            <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginTop: 8 }}>
              {regenError}
            </p>
          )}
        </div>
      )}
    </div>
  );
}

const COMMUNITY_URL = "https://reddit.com/r/ascentery";

/* The creator checks their own game. The check runs on the server; only a
   verdict and plain sentences come back, never the game's data. */
/* reviewOnly: an admin looking at someone else's game. The check is the same.
   "Fix these?" does not change their game: the repair is sent to the creator as
   a suggested fix, at no charge. "Write ending" is offered only while the game
   has no ending, and an existing ending can be read but not changed. */
function ValidatorTab({ worldId, status, isOwner, reviewOnly = false, me, setMe, onFixed }) {
  const [busy, setBusy] = useState(false);
  const [res, setRes] = useState(null);
  const [error, setError] = useState(null);
  const [communityUrl, setCommunityUrl] = useState(COMMUNITY_URL);
  const [fixing, setFixing] = useState(false);
  const [fix, setFix] = useState(null);          // what the last repair said

  /* Admin only: a game with no closing passage can be given one. The admin
     reads the draft first and saves it only if happy. */
  const isAdmin = Boolean(me?.isAdmin);
  const [endText, setEndText] = useState("");      // the saved ending, "" if none
  const [endLoaded, setEndLoaded] = useState(false);
  const [endShow, setEndShow] = useState(false);    // the saved ending's panel is open
  const [endBusy, setEndBusy] = useState(false);
  const [endDraft, setEndDraft] = useState(null);   // text being previewed
  const [endMsg, setEndMsg] = useState(null);       // { ok, text }
  const [endNote, setEndNote] = useState("");        // what to change in the next draft
  useEffect(() => {
    if (!isAdmin || status !== "ready") return;
    loadWorldData(worldId)
      .then((d) => { setEndText(typeof d?.data?.endingText === "string" ? d.data.endingText.trim() : ""); setEndLoaded(true); })
      .catch(() => setEndLoaded(false));
  }, [worldId, isAdmin, status]);
  const writeEnding = async () => {
    setEndBusy(true); setEndMsg(null);
    try { setEndDraft((await writeEndingDraft(worldId, endNote.trim())).text); }
    catch (e) { setEndMsg({ ok: false, text: e.message }); }
    finally { setEndBusy(false); }
  };
  const saveEnding = async () => {
    setEndBusy(true); setEndMsg(null);
    try {
      await saveEndingText(worldId, endDraft, Boolean(endText));
      setEndText(endDraft.trim());
      setEndDraft(null);
      setEndMsg({ ok: true, text: "Ending saved." });
      await onFixed?.();
    } catch (e) { setEndMsg({ ok: false, text: e.message }); }
    finally { setEndBusy(false); }
  };

  useEffect(() => {
    loadSetting("community_url").then((v) => setCommunityUrl(typeof v?.url === "string" && v.url ? v.url : COMMUNITY_URL)).catch(() => {});
  }, []);

  const run = async (keepFix = false) => {
    setBusy(true); setError(null);
    if (!keepFix) setFix(null);
    try {
      setRes(await checkMyWorld(worldId));
    } catch (e) {
      setRes(null);
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  /* "Fix these?": free automatic repairs first, then a model repair that is
     only kept (and only charged) if the check says it is better. Nothing of
     the game's data is ever shown. The check is run again afterwards. */
  const repair = async () => {
    setFixing(true); setError(null);
    try {
      const out = await fixMyWorld(worldId);
      setFix(out);
      if (typeof out.balance_cents === "number") setMe?.((m) => ({ ...m, balance: out.balance_cents }));
      // A suggestion leaves the live game as it was: nothing to refresh and nothing new to check.
      if (!out.suggested) {
        if (out.status === "fixed" || out.status === "partly") await onFixed?.();
        await run(true);
      }
    } catch (e) {
      setError(e.message);
    } finally {
      setFixing(false);
    }
  };

  const showFix = Boolean(res && res.verdict !== "ok" && (isOwner || reviewOnly));
  const mono = { fontFamily: T.mono, fontSize: 11.5, lineHeight: 1.7 };
  const verdictLine = !res ? null
    : res.verdict === "ok"
      ? (res.notes?.length
        ? { color: T.ochre, text: "Nothing found that stops the game being finished, but some things are worth a look (below)." }
        : { color: T.moss, text: "Looks good. The check found no problems and could follow a route through the whole game." })
      : res.verdict === "unsure"
        ? { color: T.ochre, text: "The check could not confirm every step, so it cannot promise this game can be finished. That does not mean the steps are broken; it means the check could not prove them. Play those steps yourself to be sure." }
        : { color: T.clay, text: `The check found ${res.problems.length} problem${res.problems.length === 1 ? "" : "s"} that would stop the game being finished.` };

  const List = ({ items, color }) => (
    <div style={{ ...mono, color, margin: "6px 0 14px" }}>
      {items.map((m, i) => <div key={i} style={{ marginBottom: 6 }}>{"\u2022"} {m}</div>)}
    </div>
  );

  if (status !== "ready") {
    return <Empty title="Nothing to check yet." line="This world has not finished building." />;
  }

  return (
    <div>
      <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: "0 0 18px" }}>
        {reviewOnly
          ? <>Checks whether this game can be finished from the start, and lists anything that is wrong.
              Checking does not change anything. "Fix these?" does not change the creator's game either: it
              sends them a suggested fix, which they decide whether to use. It is free for them.</>
          : <>Checks whether your game can be finished from the start, and lists anything that is wrong.
              It reads your game as it is right now. Checking does not change anything, and it is free.</>}
      </p>

      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
        <Btn kind={showFix ? "ghost" : "solid"} disabled={busy || fixing} onClick={() => run()}
          style={showFix ? { border: "1px solid " + T.ochre, color: T.ochre, padding: "8px 14px", borderRadius: 2 } : undefined}>
          {busy ? "checking\u2026" : res ? "Check again" : reviewOnly ? "Check if this world can be completed" : "Check if my world can be completed"}
        </Btn>
        {isAdmin && endLoaded && !endText && !endDraft && (
          <Btn kind="ghost" disabled={endBusy} onClick={writeEnding}
            style={{ border: "1px solid " + T.edge, padding: "8px 14px", borderRadius: 2 }}>
            {endBusy ? "writing\u2026" : "Write ending"}
          </Btn>
        )}
        {isAdmin && endLoaded && endText && (
          <Btn kind="ghost" disabled={endBusy} onClick={() => setEndShow((v) => !v)}
            style={{ border: "1px solid " + T.edge, padding: "8px 14px", borderRadius: 2 }}>
            {endShow ? "Hide ending" : "Show ending"}
          </Btn>
        )}
      </div>

      {isAdmin && endText && endShow && endDraft === null && (
        <div style={{ marginTop: 16, border: "1px solid " + T.edge, borderRadius: 2, padding: "12px 14px" }}>
          <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, marginBottom: 6 }}>
            {reviewOnly ? "Ending (read only: only its creator can change it)" : "Ending (admin only)"}
          </div>
          <p style={{ fontFamily: T.serif, fontSize: 15, lineHeight: 1.6, margin: reviewOnly ? 0 : "0 0 10px", whiteSpace: "pre-wrap" }}>{endText}</p>
          {!reviewOnly && (
            <>
              <input type="text" value={endNote} onChange={(e) => setEndNote(e.target.value)} maxLength={500}
                placeholder="Note for the rewrite (optional), e.g. make it a cliffhanger"
                style={{ ...inputStyle, width: "100%", marginBottom: 10, boxSizing: "border-box" }} />
              <Btn kind="ghost" disabled={endBusy} onClick={writeEnding}>{endBusy ? "writing\u2026" : "Rewrite"}</Btn>
            </>
          )}
        </div>
      )}

      {isAdmin && endDraft !== null && (
        <div style={{ marginTop: 16, border: "1px solid " + T.edge, borderRadius: 2, padding: "12px 14px" }}>
          <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, marginBottom: 6 }}>
            {endText ? "Rewritten ending (admin preview, you can edit it; the saved one stays until you press Save)" : "Ending (admin preview, you can edit it before saving)"}
          </div>
          <textarea value={endDraft} onChange={(e) => setEndDraft(e.target.value)} rows={6}
            style={{ ...inputStyle, width: "100%", fontFamily: T.serif, fontSize: 15, lineHeight: 1.6, boxSizing: "border-box" }} />
          <input type="text" value={endNote} onChange={(e) => setEndNote(e.target.value)} maxLength={500}
            placeholder="Note for the next draft (optional), e.g. make it a cliffhanger"
            style={{ ...inputStyle, width: "100%", marginTop: 10, boxSizing: "border-box" }} />
          <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginTop: 10 }}>
            <Btn kind="solid" disabled={endBusy || !endDraft.trim()} onClick={saveEnding}>{endBusy ? "working\u2026" : "Save"}</Btn>
            <Btn kind="ghost" disabled={endBusy} onClick={writeEnding}>Write another</Btn>
            <Btn kind="ghost" disabled={endBusy} onClick={() => { setEndDraft(null); setEndMsg(null); setEndNote(""); }}>Discard</Btn>
          </div>
        </div>
      )}
      {isAdmin && endMsg && (
        <p style={{ fontFamily: T.mono, fontSize: 11.5, marginTop: 10, color: endMsg.ok ? T.moss : T.clay }}>{endMsg.text}</p>
      )}

      {error && <p style={{ ...mono, color: T.clay, marginTop: 12 }}>{error}</p>}

      {res && (
        <div style={{ marginTop: 22, border: "1px solid " + verdictLine.color + "66", borderRadius: 2, padding: "14px 16px" }}>
          <p style={{ fontFamily: T.serif, fontSize: 16, lineHeight: 1.6, margin: "0 0 4px", color: verdictLine.color }}>
            {verdictLine.text}
          </p>
          {res.problems.length > 0 && (
            <>
              <div style={{ ...mono, color: T.boneDim, marginTop: 12 }}>Problems</div>
              <List items={res.problems} color={T.clay} />
            </>
          )}
          {res.unsure.length > 0 && (
            <>
              <div style={{ ...mono, color: T.boneDim, marginTop: 12 }}>Could not confirm</div>
              <List items={res.unsure} color={T.ochre} />
            </>
          )}
          {res.notes.length > 0 && (
            <>
              <div style={{ ...mono, color: T.boneDim, marginTop: 12 }}>Worth a look</div>
              <List items={res.notes} color={T.boneDim} />
            </>
          )}
          <div style={{ ...mono, color: T.boneDim }}>
            {res.steps} step{res.steps === 1 ? "" : "s"} in the route through your game.
          </div>
        </div>
      )}

      {fix && (
        <div style={{ ...mono, marginTop: 16, padding: "12px 14px", border: "1px solid " + T.edge, borderRadius: 2,
          color: fix.status === "fixed" ? T.moss : fix.status === "partly" ? T.ochre : T.boneDim }}>
          <div style={{ fontFamily: T.serif, fontSize: 15, lineHeight: 1.6 }}>
            {fix.status === "fixed" && "Fixed. "}
            {fix.status === "partly" && "Part of it is fixed. "}
            {fix.reply}
          </div>
          {fix.suggested && (fix.status === "fixed" || fix.status === "partly") && (
            <div style={{ marginTop: 6, color: T.boneDim }}>
              Sent to the creator as a suggested fix. Their live game is unchanged; they will see it under
              Changes / Repairs and decide whether to use it. No charge.
            </div>
          )}
          {fix.suggested && (fix.after?.problems?.length > 0 || fix.after?.unsure?.length > 0) && (
            <div style={{ marginTop: 8 }}>
              <div style={{ color: T.boneDim }}>Still open in the suggested fix</div>
              <List items={[...(fix.after.problems ?? []), ...(fix.after.unsure ?? [])]} color={T.ochre} />
            </div>
          )}
          {!fix.suggested && fix.status !== "nothing" && fix.status !== "unchanged" && (
            <div style={{ marginTop: 6, color: T.boneDim }}>
              Your previous version is kept; you can go back to it from the World tab.
              {fix.charged_cents > 0 ? ` Charged ${money(fix.charged_cents)}.` : " No charge."}
            </div>
          )}
        </div>
      )}

      {showFix && !fixing && (
        <div style={{ marginTop: 18 }}>
          <Btn kind="solid" disabled={busy} onClick={repair}>
            {reviewOnly ? <>Fix these? {"\u00b7"} send to creator</> : <>Fix these? {"\u00b7"} {money(VALIDATOR_FIX_CENTS)}</>}
          </Btn>
        </div>
      )}
      {fixing && (
        <p style={{ ...mono, color: T.boneDim, marginTop: 16 }}>
          {reviewOnly ? "Repairing the game and preparing the suggested fix… this can take a minute." : "Repairing your game… this can take a minute."}
        </p>
      )}

      {communityUrl && res && res.verdict !== "ok" && !reviewOnly && (
        <div style={{ marginTop: 30, paddingTop: 18, borderTop: "1px solid " + T.edge }}>
          <p style={{ ...mono, color: T.boneDim, margin: 0 }}>
            Still not working? Request help from the{" "}
            <a href={communityUrl} target="_blank" rel="noopener noreferrer"
              style={{ color: T.ochre, textDecoration: "underline" }}>
              community
            </a>
          </p>
        </div>
      )}
    </div>
  );
}

/* What Ascentery (an admin) has offered for this game, and the one backup.
   No world JSON ever reaches this panel: only the admin's comment and summary.
   Accepting and going back both happen inside the database, and both need the
   game to be unpublished first. */
function SuggestedFixPanel({ worldId, published, canAct, tick, onChanged }) {
  const [status, setStatus] = useState(null);
  const [busy, setBusy] = useState(false);
  const [confirm, setConfirm] = useState(null);       // "apply" | "revert" | null
  const [error, setError] = useState(null);
  const [done, setDone] = useState(null);

  const load = () => {
    loadSuggestedFixStatus(worldId).then(setStatus).catch(() => setStatus(null));
  };
  useEffect(() => { load(); }, [worldId, tick]);

  if (!status) return null;
  // Nothing on offer and nothing kept: no panel at all. A kept backup with no
  // fix waiting shows only the backup part, and only to the creator.
  const onlyBackup = !status.has_suggestion;
  if (onlyBackup && (!status.has_backup || !canAct)) return null;

  const run = async (kind) => {
    setBusy(true); setError(null); setDone(null);
    try {
      if (kind === "apply") await applySuggestedFix(worldId);
      else await revertToBackup(worldId);
      setConfirm(null);
      setDone(kind === "apply"
        ? "Done. Your previous version is kept; go back any time. Publish your game again when you are ready."
        : "Done. The version you just left is kept, so going back again returns you to it. Publish your game again when you are ready.");
      await onChanged?.();
    } catch (e) {
      setError(e.message);
    } finally {
      setBusy(false);
    }
  };

  const when = (iso) => (iso ? new Date(iso).toLocaleString() : "");
  const lines = String(status.summary ?? "").split("\n").filter(Boolean);
  const mono = { fontFamily: T.mono, fontSize: 11, lineHeight: 1.7, color: T.boneDim };

  return (
    <div style={{ border: "1px solid " + (!onlyBackup ? T.ochre + "88" : T.edge), borderRadius: 2,
      padding: "14px 16px", marginBottom: 24 }}>
      {!onlyBackup && (
        <div style={{ fontFamily: T.mono, fontSize: 11, color: T.ochre, marginBottom: 8 }}>
          Ascentery suggested fix
        </div>
      )}

      {!onlyBackup && (
        <>
          <p style={{ fontFamily: T.serif, fontSize: 15, lineHeight: 1.6, margin: "0 0 8px" }}>{status.note}</p>
          {lines.length > 0 && (
            <div style={{ ...mono, marginBottom: 8 }}>
              {lines.map((l, i) => <div key={i}>• {l}</div>)}
            </div>
          )}
          <div style={{ ...mono, marginBottom: 8 }}>Suggested {when(status.suggested_at)}</div>
          {status.stale && (
            <p style={{ ...mono, color: T.clay, margin: "0 0 8px" }}>
              You have changed this game since this fix was made. Using it replaces those changes.
              Your current version is kept, so you can go back.
            </p>
          )}
        </>
      )}

      {canAct && (
        <>
          {published && !onlyBackup && (
            <p style={{ ...mono, color: T.clay, margin: "0 0 8px" }}>
              Unpublish your game first (Settings), then use this, then publish again.
            </p>
          )}
          {!onlyBackup && (confirm === "apply" ? (
            <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
              <span style={mono}>This replaces your game with Ascentery's version. Your current one is kept.</span>
              <Btn disabled={busy} onClick={() => run("apply")}>{busy ? "working…" : "Yes, use it"}</Btn>
              <Btn kind="ghost" disabled={busy} onClick={() => setConfirm(null)}>Cancel</Btn>
            </div>
          ) : (
            <Btn disabled={!status.has_suggestion || published || busy} onClick={() => { setConfirm("apply"); setError(null); setDone(null); }}>
              Use Ascentery's suggested fix
            </Btn>
          ))}

          {status.has_backup && (
            <div style={onlyBackup ? {} : { marginTop: 14, paddingTop: 12, borderTop: "1px solid " + T.edge }}>
              {published && onlyBackup && (
                <p style={{ ...mono, color: T.clay, margin: "0 0 8px" }}>
                  Unpublish your game first to go back.
                </p>
              )}
              <div style={{ ...mono, marginBottom: 8 }}>
                Previous version kept: {status.backup_reason} ({when(status.backup_at)})
              </div>
              {confirm === "revert" ? (
                <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
                  <span style={mono}>This swaps your game with the previous version.</span>
                  <Btn disabled={busy} onClick={() => run("revert")}>{busy ? "working…" : "Yes, go back"}</Btn>
                  <Btn kind="ghost" disabled={busy} onClick={() => setConfirm(null)}>Cancel</Btn>
                </div>
              ) : (
                <Btn kind="ghost" disabled={published || busy} onClick={() => { setConfirm("revert"); setError(null); setDone(null); }}
                  style={{ border: "1px solid " + T.boneDim, padding: "8px 14px", borderRadius: 2 }}>
                  Go back to the previous version
                </Btn>
              )}
            </div>
          )}
        </>
      )}

      {error && <p style={{ ...mono, color: T.clay, margin: "10px 0 0" }}>{error}</p>}
      {done && <p style={{ ...mono, color: T.moss, margin: "10px 0 0" }}>{done}</p>}
    </div>
  );
}

function RepairTab({ worldId, title, isAdmin, isOwner, published, onJsonSaved }) {
  const [world, setWorld] = useState(null);
  const [loadError, setLoadError] = useState(null);
  const [query, setQuery] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [needsFunds, setNeedsFunds] = useState(false);
  const [result, setResult] = useState(null);       // { status, reply, cost_cents }
  const [copied, setCopied] = useState(false);
  const [checkWalkthrough, setCheckWalkthrough] = useState(false);
  const [jsonDraft, setJsonDraft] = useState(null);   // editable text in the JSON box
  const [jsonSaving, setJsonSaving] = useState(false);
  const [syncing, setSyncing] = useState(false);
  const [syncMsg, setSyncMsg] = useState(null);
  const [jsonSaveError, setJsonSaveError] = useState(null);
  const [jsonSaved, setJsonSaved] = useState(false);
  // Admin: suggest a fix to the creator instead of overwriting their live game.
  const [fixNote, setFixNote] = useState("");
  const [fixSummary, setFixSummary] = useState("");
  const [fixCheck, setFixCheck] = useState(null);      // { errors, warnings, handChecks, steps }
  const [fixBusy, setFixBusy] = useState(false);
  const [fixMsg, setFixMsg] = useState(null);          // { ok: bool, text }
  const [fixTick, setFixTick] = useState(0);           // bumps to make the panel re-read its status
  const [fixPending, setFixPending] = useState(false);

  const refresh = () => {
    loadWorldData(worldId)
      .then(({ data }) => { setWorld(data); setJsonDraft(JSON.stringify(data, null, 2)); })
      .catch((e) => setLoadError(e.message));
  };
  useEffect(() => { refresh(); }, [worldId]);

  const send = async () => {
    if (!query.trim() || busy) return;
    setBusy(true); setError(null); setNeedsFunds(false); setCheckWalkthrough(false);
    try {
      const res = await repairWorld(worldId, query.trim());
      setResult(res);
      setWorld(res.world);
      setQuery("");
    } catch (e) {
      setError(e.message);
      setNeedsFunds(Boolean(e.needsFunds));
    } finally {
      setBusy(false);
    }
  };

  const copyJson = async () => {
    const text = JSON.stringify(world, null, 2);
    // The modern clipboard API is not universally available — older
    // Safari and some embedded webviews either lack it or reject it
    // depending on permissions, and fail silently rather than throwing
    // something visible. A classic textarea + execCommand fallback covers
    // far more of those cases, so this only reports failure if both fail.
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
      return;
    } catch { /* fall through to the classic approach below */ }

    try {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.style.position = "fixed";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.focus();
      ta.select();
      const ok = document.execCommand("copy");
      document.body.removeChild(ta);
      if (!ok) throw new Error("execCommand copy returned false");
      setCopied(true);
      setTimeout(() => setCopied(false), 1600);
    } catch {
      setError("Could not copy — your browser may be blocking clipboard access. Select the text in the box above and copy it manually.");
    }
  };

  /* Matches the picture slots to the SAVED game: slots for new things are
     added, never-drawn slots for things that are gone are deleted, drawn ones
     are retired to "No longer here". The text in the box is not read. */
  const runSync = async () => {
    setSyncMsg(null);
    setSyncing(true);
    try {
      const n = await syncArtEntries(worldId);
      setSyncMsg(n > 0 ? `${n} change${n === 1 ? "" : "s"} made` : "already in step");
      if (n > 0) onJsonSaved?.();
    } catch (e) {
      setSyncMsg(`Could not sync: ${e.message}`);
    } finally {
      setSyncing(false);
    }
  };

  const saveJson = async () => {
    setJsonSaveError(null);
    let parsed;
    try {
      parsed = JSON.parse(jsonDraft);
    } catch (e) {
      setJsonSaveError(`Invalid JSON: ${e.message}`);
      return;
    }
    setJsonSaving(true);
    try {
      await saveWorldData(worldId, parsed);
      setWorld(parsed);
      setJsonSaved(true);
      setTimeout(() => setJsonSaved(false), 2000);
      onJsonSaved?.();
    } catch (e) {
      setJsonSaveError(e.message);
    } finally {
      setJsonSaving(false);
    }
  };

  useEffect(() => {
    if (!isAdmin) return;
    loadSuggestedFixStatus(worldId).then((st) => setFixPending(Boolean(st?.has_suggestion))).catch(() => {});
  }, [worldId, isAdmin, fixTick]);

  const draftWorld = () => {
    try { return JSON.parse(jsonDraft); } catch { return null; }
  };

  /** Runs the generator's own checks on what is in the box. Returns the result,
      or null if the box is not a world. */
  const runFixCheck = async () => {
    const w = draftWorld();
    if (!w || typeof w !== "object" || typeof w.rooms !== "object") {
      setFixMsg({ ok: false, text: "The box does not contain a valid world." });
      return null;
    }
    setFixBusy(true); setFixMsg(null);
    try {
      const r = await checkWorld(w);
      setFixCheck(r);
      if (!fixSummary.trim() && world) setFixSummary(summarizeWorldDiff(world, w).join("\n"));
      return r;
    } catch (e) {
      setFixMsg({ ok: false, text: e.message });
      return null;
    } finally {
      setFixBusy(false);
    }
  };

  const sendFix = async () => {
    const w = draftWorld();
    const r = await runFixCheck();
    if (!r || !w) return;
    if (!r.ok) {
      setFixMsg({ ok: false, text: "Not sent: the world still has errors (listed above). Fix them first." });
      return;
    }
    setFixBusy(true);
    try {
      const summary = fixSummary.trim() || summarizeWorldDiff(world ?? {}, w).join("\n");
      await sendSuggestedFix(worldId, w, fixNote.trim(), summary);
      setFixMsg({ ok: true, text: "Sent. The creator will see it under Changes / Repairs." });
      setFixNote(""); setFixSummary(""); setFixCheck(null);
      setFixTick((n) => n + 1);
    } catch (e) {
      setFixMsg({ ok: false, text: e.message });
    } finally {
      setFixBusy(false);
    }
  };

  const loadPending = async () => {
    setFixBusy(true); setFixMsg(null);
    try {
      const d = await loadSuggestedFixData(worldId);
      if (d) { setJsonDraft(JSON.stringify(d, null, 2)); setFixCheck(null); setFixMsg({ ok: true, text: "The pending fix is loaded in the box. Edit it, then send again to replace it." }); }
      else setFixMsg({ ok: false, text: "There is no pending fix." });
    } catch (e) {
      setFixMsg({ ok: false, text: e.message });
    } finally {
      setFixBusy(false);
    }
  };

  const withdrawFix = async () => {
    setFixBusy(true); setFixMsg(null);
    try {
      await withdrawSuggestedFix(worldId);
      setFixMsg({ ok: true, text: "Withdrawn." });
      setFixTick((n) => n + 1);
    } catch (e) {
      setFixMsg({ ok: false, text: e.message });
    } finally {
      setFixBusy(false);
    }
  };

  const walkthrough = checkWalkthrough && world ? buildWalkthrough(world) : null;

  return (
    <div style={{ maxWidth: 720 }}>
      {!isOwner && (
        <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: "0 0 20px" }}>
          Build a fix in the box below, check it, and send it. The creator decides whether to use it.
        </p>
      )}
      {isOwner && <p style={{ fontFamily: T.serif, fontSize: 15, color: T.boneDim, lineHeight: 1.6, margin: "0 0 20px" }}>
        Describe a bug to fix, or a change you want made on purpose — "once inside the room there
        is no exit and the door is locked," or "swap the flute puzzle for a rubber-mouse decoy."
        The model reads the whole world and makes the change, but nothing is ever applied unless it
        passes the same check every generated world already has to pass, so a change that breaks
        something else is refused rather than saved. Costs {money(REPAIR_CENTS)} whether or not anything
        actually changes, since the attempt happens either way. Every change here is undoable from
        the World tab, the same as any other amendment.
      </p>}

      <SuggestedFixPanel worldId={worldId} published={published} canAct={isOwner} tick={fixTick}
        onChanged={async () => { setFixTick((n) => n + 1); refresh(); await onJsonSaved?.(); }} />

      {isAdmin && (
        <div style={{ marginBottom: 24 }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 8, flexWrap: "wrap" }}>
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>
              {isOwner ? "World JSON (admin only)" : "Build a fix (admin only)"}
            </div>
            <Btn kind="ghost" onClick={copyJson} disabled={!world}>
              {copied ? "copied" : "copy"}
            </Btn>
            {isOwner && (
              <Btn kind="ghost" disabled={jsonSaving || !world || jsonDraft === JSON.stringify(world, null, 2)} onClick={saveJson}>
                {jsonSaving ? "saving…" : jsonSaved ? "saved" : "overwrite live game"}
              </Btn>
            )}
            <Btn kind="ghost" disabled={syncing} onClick={runSync}>
              {syncing ? "syncing…" : "sync pictures"}
            </Btn>
            {syncMsg && <span style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>{syncMsg}</span>}
            {jsonDraft != null && world && jsonDraft !== JSON.stringify(world, null, 2) && (
              <span style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim }}>
                sync uses the saved game, not the unsaved text in the box
              </span>
            )}
          </div>
          {loadError ? (
            <p style={{ fontFamily: T.mono, fontSize: 12, color: T.clay }}>{loadError}</p>
          ) : (
            <textarea
              value={jsonDraft ?? (world ? JSON.stringify(world, null, 2) : "loading…")}
              onChange={(e) => { setJsonDraft(e.target.value); setJsonSaveError(null); }}
              rows={18}
              spellCheck={false}
              style={{ ...inputStyle, fontFamily: T.mono, fontSize: 11, lineHeight: 1.5, resize: "vertical" }}
            />
          )}
          {jsonSaveError && (
            <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, marginTop: 6 }}>
              {jsonSaveError}
            </p>
          )}

          <div style={{ marginTop: 16, paddingTop: 14, borderTop: "1px solid " + T.edge }}>
            <div style={{ fontFamily: T.mono, fontSize: 11, color: T.ochre, marginBottom: 6 }}>
              Suggest this as a fix (the creator chooses whether to use it)
            </div>
            <p style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, lineHeight: 1.7, margin: "0 0 10px" }}>
              Sends what is in the box as a suggested fix instead of changing the live game. It is checked
              first, and is not sent if the check finds errors.{isOwner
                ? ' "Overwrite live game" above skips all of this and cannot be undone.'
                : " Only the creator can put it live."}
            </p>
            <input value={fixNote} onChange={(e) => setFixNote(e.target.value)} maxLength={1000}
              placeholder="Comment for the creator (required): what was wrong, what you changed"
              style={{ ...inputStyle, width: "100%", marginBottom: 8 }} />
            <textarea value={fixSummary} onChange={(e) => setFixSummary(e.target.value)} rows={3}
              placeholder="What changed, one line each (filled in from the differences when you check)"
              style={{ ...inputStyle, fontFamily: T.mono, fontSize: 11, lineHeight: 1.5, resize: "vertical", width: "100%", marginBottom: 8 }} />
            <div style={{ display: "flex", gap: 10, flexWrap: "wrap", alignItems: "center" }}>
              <Btn kind="ghost" disabled={fixBusy || !world} onClick={runFixCheck}>
                {fixBusy ? "working…" : "Check"}
              </Btn>
              <Btn disabled={fixBusy || !world || fixNote.trim().length < 3 || jsonDraft === JSON.stringify(world, null, 2)}
                onClick={sendFix}>
                Send as suggested fix
              </Btn>
              {fixPending && (
                <>
                  <Btn kind="ghost" disabled={fixBusy} onClick={loadPending}>Load pending fix</Btn>
                  <Btn kind="ghost" disabled={fixBusy} onClick={withdrawFix}>Withdraw it</Btn>
                </>
              )}
            </div>
            {fixCheck && (
              <div style={{ marginTop: 10, fontFamily: T.mono, fontSize: 11, lineHeight: 1.7 }}>
                <div style={{ color: fixCheck.ok ? T.moss : T.clay }}>
                  {fixCheck.ok ? "No errors." : `${fixCheck.errors.length} error${fixCheck.errors.length === 1 ? "" : "s"} — must be fixed before sending:`}
                </div>
                {fixCheck.errors.map((m, i) => <div key={"e" + i} style={{ color: T.clay }}>• {m}</div>)}
                {fixCheck.warnings.length > 0 && (
                  <div style={{ color: T.ochre, marginTop: 6 }}>{fixCheck.warnings.length} warning{fixCheck.warnings.length === 1 ? "" : "s"} (do not block):</div>
                )}
                {fixCheck.warnings.map((m, i) => <div key={"w" + i} style={{ color: T.boneDim }}>• {m}</div>)}
                {fixCheck.handChecks.length > 0 && (
                  <div style={{ color: T.ochre, marginTop: 6 }}>The walkthrough could not resolve:</div>
                )}
                {fixCheck.handChecks.map((m, i) => <div key={"h" + i} style={{ color: T.boneDim }}>• {m}</div>)}
                <div style={{ color: T.boneDim, marginTop: 6 }}>Walkthrough: {fixCheck.steps} steps.</div>
              </div>
            )}
            {fixMsg && (
              <p style={{ fontFamily: T.mono, fontSize: 11.5, color: fixMsg.ok ? T.moss : T.clay, marginTop: 8 }}>
                {fixMsg.text}
              </p>
            )}
          </div>
        </div>
      )}

      {isOwner && <>
      <div style={{ borderTop: "1px solid " + T.edge, paddingTop: 18, marginBottom: 18 }}>
        <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, marginBottom: 8 }}>
          Response
        </div>
        {result ? (
          <div style={{ border: "1px solid " + (result.status === "modified" ? T.moss : T.edge) + "88",
            borderRadius: 2, padding: "12px 14px" }}>
            <div style={{ fontFamily: T.mono, fontSize: 10.5, color: result.status === "modified" ? T.moss : T.boneDim,
              marginBottom: 8 }}>
              {result.status === "modified" ? "repaired — the world was changed" : "unchanged"}
            </div>
            <p style={{ fontFamily: T.serif, fontSize: 15, lineHeight: 1.6, margin: 0 }}>{result.reply}</p>

            {isAdmin && result.rejected_proposal && (
              <div style={{ marginTop: 14, paddingTop: 14, borderTop: "1px solid " + T.edge }}>
                <div style={{ fontFamily: T.mono, fontSize: 10.5, color: T.ochre, marginBottom: 8 }}>
                  Admin only — what was proposed and rejected
                </div>
                <pre style={{ maxHeight: 320, overflow: "auto", margin: 0, padding: 10,
                  background: T.ground, border: "1px solid " + T.edge, borderRadius: 2,
                  fontFamily: T.mono, fontSize: 10.5, lineHeight: 1.5, color: T.boneDim,
                  whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
                  {JSON.stringify(result.rejected_proposal, null, 2)}
                </pre>
              </div>
            )}
          </div>
        ) : (
          <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>Nothing asked yet.</p>
        )}
      </div>

      {result && (
        <div style={{ marginBottom: 18 }}>
          {!checkWalkthrough ? (
            <Btn kind="ghost" onClick={() => setCheckWalkthrough(true)}>
              Check the walkthrough
            </Btn>
          ) : (
            <>
              <p style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim, lineHeight: 1.7, margin: "0 0 12px" }}>
                Computed directly from the world as it stands right now — not a second AI call,
                which could describe a step that does not actually work. This is the same
                deterministic check the Walkthrough tab uses, so if it completes cleanly here, the
                problem is genuinely solved.
              </p>
              {walkthrough && !walkthrough.length && (
                <p style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>No quests in this world.</p>
              )}
              {walkthrough && walkthrough.map((s, i) => (
                <div key={i} style={{ fontFamily: T.mono, fontSize: 11.5, lineHeight: 1.9, color: T.boneDim,
                  borderBottom: "1px solid " + T.edge + "55", padding: "6px 0" }}>
                  <span style={{ color: s.note ? T.clay : T.boneDim }}>{i + 1}. {s.goal}</span>
                  {s.note && <span style={{ color: T.clay }}> — {s.note}</span>}
                </div>
              ))}
            </>
          )}
        </div>
      )}

      <Field label="What you want changed">
        <textarea value={query} onChange={(e) => setQuery(e.target.value)} rows={4}
          placeholder="Once inside the room there is no exit and the door is locked. Or: instead of the flute, let the player find a rubber mouse to distract the cat with."
          style={{ ...inputStyle, lineHeight: 1.6, resize: "vertical" }} />
      </Field>

      {error && (
        <p style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay, margin: "-8px 0 14px" }}>
          {error}
          {needsFunds && <Btn kind="ghost" style={{ marginLeft: 10 }}>Add funds</Btn>}
        </p>
      )}

      <Btn kind="solid" disabled={busy || !query.trim()} onClick={send}>
        {busy ? "looking…" : `Ask · ${money(REPAIR_CENTS)}`}
      </Btn>
      </>}
    </div>
  );
}
