// src/catalog/studioRender.js
//
// Rendering for the Studio video editor. A project (layers of clips) becomes ONE ffmpeg
// command, which runs inside the browser with ffmpeg.wasm. Nothing is uploaded for this:
// the clips are read, stitched and encoded on the creator's own computer, so editing
// costs nothing. The engine itself (about 30 MB) is fetched from a CDN the first time an
// edit is exported, and the browser keeps it afterwards.
//
// A project:
//   { name, tracks: [ { id, kind: "video" | "audio", clips: [ clip ] } ] }
//   clip  = { id, itemId, name, start, in, out, srcDur, mute }
//           start = where it sits on the timeline (seconds); in..out = the part of the
//           source that plays. Its length on the timeline is out - in.
// tracks[0] is the TOP layer. A clip on a higher video layer covers whatever is under it;
// the audio of every clip that is not muted is mixed together.

export const OUT_W = 854;
export const OUT_H = 480;          // 480p, 16:9
export const OUT_FPS = 24;
/** The longest edit that can be exported, in seconds (browser memory is the reason). */
export const MAX_EDIT_SECONDS = 120;

const FFMPEG_VERSION = "0.12.10";
const CORE_VERSION = "0.12.6";
const CDNS = [
  (pkg, ver) => `https://unpkg.com/${pkg}@${ver}/dist/umd`,
  (pkg, ver) => `https://cdn.jsdelivr.net/npm/${pkg}@${ver}/dist/umd`,
];

export const clipLength = (c) => Math.max(0, c.out - c.in);

export function projectDuration(project) {
  let d = 0;
  for (const t of project.tracks) for (const c of t.clips) d = Math.max(d, c.start + clipLength(c));
  return d;
}

const f3 = (n) => Number(n).toFixed(3);

/**
 * The ffmpeg arguments for a project.
 *   sources: { [itemId]: { file: "in0.mp4", hasAudio: boolean } }
 * Returns { args, outFile, duration }.
 */
export function buildRenderArgs(project, sources, outFile = "out.mp4") {
  const total = projectDuration(project);
  if (!(total > 0)) throw new Error("There is nothing on the timeline yet.");

  const ids = [];
  for (const t of project.tracks) for (const c of t.clips) if (!ids.includes(c.itemId)) ids.push(c.itemId);
  const idx = Object.fromEntries(ids.map((id, i) => [id, i]));

  const args = [];
  for (const id of ids) args.push("-i", sources[id].file);

  const g = [];
  g.push(`color=c=black:s=${OUT_W}x${OUT_H}:r=${OUT_FPS}:d=${f3(total)},format=yuv420p[b0]`);
  let last = "b0", n = 0;
  const audio = [];

  // Bottom layer first, so higher layers end up on top.
  for (const tr of [...project.tracks].reverse()) {
    const clips = [...tr.clips].sort((a, b) => a.start - b.start);
    for (const c of clips) {
      const i = idx[c.itemId];
      const end = c.start + clipLength(c);
      n++;
      if (tr.kind === "video") {
        g.push(
          `[${i}:v]trim=start=${f3(c.in)}:end=${f3(c.out)},setpts=PTS-STARTPTS,fps=${OUT_FPS},` +
          `scale=${OUT_W}:${OUT_H}:force_original_aspect_ratio=decrease,` +
          `pad=${OUT_W}:${OUT_H}:(ow-iw)/2:(oh-ih)/2:black,setsar=1,format=yuv420p,` +
          `setpts=PTS+${f3(c.start)}/TB[v${n}]`);
        g.push(`[${last}][v${n}]overlay=eof_action=pass:enable='between(t,${f3(c.start)},${f3(end)})'[b${n}]`);
        last = `b${n}`;
      }
      if (!c.mute && sources[c.itemId].hasAudio) {
        const ms = Math.round(c.start * 1000);
        g.push(
          `[${i}:a]atrim=start=${f3(c.in)}:end=${f3(c.out)},asetpts=PTS-STARTPTS,aresample=44100,` +
          `aformat=sample_fmts=fltp:channel_layouts=stereo,adelay=${ms}|${ms}[a${n}]`);
        audio.push(`[a${n}]`);
      }
    }
  }

  // A silent base the whole length of the edit, so the output always has an audio track.
  g.push(`anullsrc=r=44100:cl=stereo,atrim=duration=${f3(total)},asetpts=PTS-STARTPTS[a0]`);
  g.push(`[a0]${audio.join("")}amix=inputs=${audio.length + 1}:duration=first:normalize=0[aout]`);

  args.push(
    "-filter_complex", g.join(";"),
    "-map", `[${last}]`, "-map", "[aout]",
    "-t", f3(total),
    "-c:v", "libx264", "-preset", "veryfast", "-crf", "23", "-pix_fmt", "yuv420p", "-r", String(OUT_FPS),
    "-c:a", "aac", "-b:a", "128k", "-ar", "44100",
    "-movflags", "+faststart", "-y", outFile,
  );
  return { args, outFile, duration: total };
}

/* ---------- running it in the browser ---------- */

let engine = null;        // Promise<FFmpeg>
let current = null;       // the FFmpeg instance of a render in progress

async function blobUrl(url, type) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`${r.status}`);
  return URL.createObjectURL(new Blob([await r.arrayBuffer()], { type }));
}

function addScript(src) {
  return new Promise((resolve, reject) => {
    const el = document.createElement("script");
    el.src = src; el.async = true;
    el.onload = () => resolve();
    el.onerror = () => { el.remove(); reject(new Error("script")); };
    document.head.appendChild(el);
  });
}

// ffmpeg.wasm comes from a CDN: the small wrapper (a script tag), its worker, and the engine
// itself. The worker and engine go through blob: addresses because a browser will not start
// a worker from another site's address directly. Giving the wrapper a worker address makes it
// start a MODULE worker, which needs the ES-module build of the core; the older UMD build is
// kept as a second try. The 30 MB engine file is fetched once and reused between tries.
export function loadEngine(onStatus = () => {}) {
  if (!engine) {
    engine = (async () => {
      onStatus("Loading the video engine (about 30 MB, once)…");
      let lastErr = null;
      for (const cdn of CDNS) {
        let wasmURL = null, workerURL = null;
        try {
          const wrap = cdn("@ffmpeg/ffmpeg", FFMPEG_VERSION);
          const coreBase = (kind) => cdn("@ffmpeg/core", CORE_VERSION).replace(/\/umd$/, `/${kind}`);
          if (!window.FFmpegWASM) await addScript(`${wrap}/ffmpeg.js`);
          workerURL = await blobUrl(`${wrap}/814.ffmpeg.js`, "text/javascript");
          wasmURL = await blobUrl(`${coreBase("esm")}/ffmpeg-core.wasm`, "application/wasm");
          for (const kind of ["esm", "umd"]) {
            const ff = new window.FFmpegWASM.FFmpeg();
            try {
              await ff.load({
                classWorkerURL: workerURL,
                coreURL: await blobUrl(`${coreBase(kind)}/ffmpeg-core.js`, "text/javascript"),
                wasmURL,
              });
              return ff;
            } catch (e) {
              lastErr = e;
              try { ff.terminate(); } catch { /* never started */ }
            }
          }
        } catch (e) { lastErr = e; }
      }
      throw new Error("Could not load the video engine. Check your connection and try again." +
        (lastErr ? ` (${String(lastErr.message || lastErr).slice(0, 80)})` : ""));
    })().catch((e) => { engine = null; throw e; });
  }
  return engine;
}

/** Does this file have an audio stream? Asked of ffmpeg itself (it prints its streams). */
async function hasAudioStream(ff, file) {
  const lines = [];
  const on = ({ message }) => lines.push(String(message));
  ff.on("log", on);
  try { await ff.exec(["-hide_banner", "-i", file]); } catch { /* it always "fails": no output file */ }
  ff.off("log", on);
  return lines.some((l) => /Stream #\d+:\d+.*Audio:/.test(l));
}

/** Stop a render in progress. The engine is rebuilt the next time it is needed. */
export function cancelRender() {
  if (current) { try { current.terminate(); } catch { /* already gone */ } }
  current = null;
  engine = null;
}

/**
 * Render a project. getFile(itemId) -> Promise<Uint8Array> (the clip's bytes).
 * onStatus(text) for what it is doing, onProgress(0..1) while encoding.
 * Returns the MP4 as a Uint8Array.
 */
export async function renderProject(project, { getFile, onStatus = () => {}, onProgress = () => {} }) {
  const total = projectDuration(project);
  if (total > MAX_EDIT_SECONDS) {
    throw new Error(`An edit can be at most ${MAX_EDIT_SECONDS / 60} minutes. This one is ${Math.ceil(total)} seconds.`);
  }
  const ff = await loadEngine(onStatus);
  current = ff;

  const ids = [];
  for (const t of project.tracks) for (const c of t.clips) if (!ids.includes(c.itemId)) ids.push(c.itemId);

  const sources = {};
  const written = [];
  try {
    for (let i = 0; i < ids.length; i++) {
      onStatus(`Reading clip ${i + 1} of ${ids.length}…`);
      const file = `in${i}.mp4`;
      await ff.writeFile(file, await getFile(ids[i]));
      written.push(file);
      sources[ids[i]] = { file, hasAudio: await hasAudioStream(ff, file) };
    }
    const { args, outFile } = buildRenderArgs(project, sources);

    onStatus("Rendering…");
    const logs = [];
    const onLog = ({ message }) => { logs.push(String(message)); if (logs.length > 40) logs.shift(); };
    const onProg = ({ progress }) => onProgress(Math.max(0, Math.min(1, Number(progress) || 0)));
    ff.on("log", onLog);
    ff.on("progress", onProg);
    let code;
    try { code = await ff.exec(args); }
    finally { ff.off("log", onLog); ff.off("progress", onProg); }
    if (code !== 0) {
      const tail = logs.filter((l) => l.trim()).slice(-2).join(" ").slice(0, 160);
      throw new Error("The video could not be rendered." + (tail ? ` (${tail})` : ""));
    }
    written.push(outFile);
    const out = await ff.readFile(outFile);
    onProgress(1);
    return out;
  } finally {
    for (const f of written) { try { await ff.deleteFile(f); } catch { /* gone */ } }
    if (current === ff) current = null;
  }
}
