// src/catalog/StudioVideoEditor.jsx
//
// The Studio's video editor: a main video display, and under it a timeline with layers.
// Clips can be trimmed at either end, moved, split, muted, and stacked on several video or
// audio layers, so several videos can be stitched into one. Everything is edited on the
// creator's own computer and rendered there (see studioRender.js), so editing is free.
//
// Desktop only for now.
import React, { useState, useEffect, useRef, useCallback, useMemo } from "react";
import {
  fetchStudioVideo,
  putStudioVideo,
  listStudioProjects,
  getStudioProject,
  saveStudioProject,
  deleteStudioProject,
} from "../lib/db";
import { renderProject, cancelRender, projectDuration, clipLength, MAX_EDIT_SECONDS } from "./studioRender";
import { useNarrow } from "../hooks";
import { T } from "../theme";

const LABEL_W = 92;        // the track-name column
const ROW_H = 46;
const RULER_H = 26;
const MIN_CLIP = 0.2;      // shortest a clip can be trimmed to, in seconds
const uid = () => Math.random().toString(36).slice(2, 9);
const clipEnd = (c) => c.start + clipLength(c);
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));

const fmt = (t) => {
  t = Math.max(0, t);
  const m = Math.floor(t / 60);
  const s = t - m * 60;
  return `${m}:${s < 10 ? "0" : ""}${s.toFixed(1)}`;
};
const fmtClock = (sec) => `${Math.floor(sec / 60)}:${String(Math.floor(sec % 60)).padStart(2, "0")}`;

const label = (n) => (n && n.trim() ? n.trim() : "Untitled");

function readDuration(url) {
  return new Promise((resolve, reject) => {
    const v = document.createElement("video");
    v.preload = "metadata";
    v.muted = true;
    v.onloadedmetadata = () => { const d = v.duration; v.removeAttribute("src"); v.load(); Number.isFinite(d) ? resolve(d) : reject(new Error("no length")); };
    v.onerror = () => reject(new Error("Could not read that video."));
    v.src = url;
  });
}

const CSS = `
@keyframes sve-sweep { 0% { transform: translateX(-100%); } 100% { transform: translateX(260%); } }
@keyframes sve-pulse { 0%,100% { opacity: .35; } 50% { opacity: 1; } }
.sve-clip:hover { filter: brightness(1.15); }
`;

export default function StudioVideoEditor({ item, items, onBack, onSaved }) {
  const narrow = useNarrow();
  const videos = useMemo(() => (items ?? []).filter((i) => i.kind === "video"), [items]);
  const byId = useMemo(() => Object.fromEntries(videos.map((v) => [v.id, v])), [videos]);

  const [project, setProject] = useState(null);       // { tracks }
  const [pname, setPname] = useState(`${label(item.name)} edit`);
  const [projectId, setProjectId] = useState("");
  const [loadErr, setLoadErr] = useState(null);
  const [t, setT] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [pps, setPps] = useState(40);                 // pixels per second (the zoom)
  const [sel, setSel] = useState(null);               // { trackId, clipId }
  const [trackSel, setTrackSel] = useState(null);     // where "add" puts a clip
  const [dirty, setDirty] = useState(false);
  const [past, setPast] = useState([]);
  const [future, setFuture] = useState([]);
  const [note, setNote] = useState(null);             // { ok, text }
  const [leaving, setLeaving] = useState(false);
  const [projects, setProjects] = useState(null);     // the saved-edits list, once opened
  const [askReplace, setAskReplace] = useState(false);
  const [exp, setExp] = useState(null);               // the export overlay state

  const projRef = useRef(null); projRef.current = project;
  const tRef = useRef(0); tRef.current = t;
  const ppsRef = useRef(40); ppsRef.current = pps;
  const gesture = useRef(null);
  const vidEls = useRef({});          // trackId -> <video>
  const rowEls = useRef({});          // trackId -> row element
  const scrollRef = useRef(null);
  const fileCache = useRef(new Map());
  const raf = useRef(0);
  const clock = useRef({ last: 0 });

  /* ---------- starting point: the video that was opened ---------- */
  useEffect(() => {
    let off = false;
    readDuration(item.url)
      .then((d) => {
        if (off) return;
        const vt = { id: uid(), kind: "video", label: "Video 1", clips: [{ id: uid(), itemId: item.id, name: label(item.name), start: 0, in: 0, out: d, srcDur: d, mute: false }] };
        const at = { id: uid(), kind: "audio", label: "Audio 1", clips: [] };
        setProject({ tracks: [vt, at] });
        setTrackSel(vt.id);
      })
      .catch((e) => { if (!off) setLoadErr(e.message || "Could not open this video."); });
    return () => { off = true; };
  }, [item.id, item.url, item.name]);

  /* ---------- history ---------- */
  const commit = useCallback((next) => {
    setPast((p) => [...p.slice(-60), projRef.current]);
    setFuture([]);
    setProject(next);
    setDirty(true);
  }, []);
  const undo = () => {
    if (!past.length) return;
    setFuture((f) => [projRef.current, ...f]);
    setProject(past[past.length - 1]);
    setPast((p) => p.slice(0, -1));
    setDirty(true);
  };
  const redo = () => {
    if (!future.length) return;
    setPast((p) => [...p, projRef.current]);
    setProject(future[0]);
    setFuture((f) => f.slice(1));
    setDirty(true);
  };

  const total = project ? projectDuration(project) : 0;
  const tooLong = total > MAX_EDIT_SECONDS + 0.001;

  /* ---------- editing operations ---------- */
  const mapClips = (fn) => ({ ...project, tracks: project.tracks.map((tr) => ({ ...tr, clips: fn(tr) })) });
  const selClip = sel && project ? project.tracks.find((x) => x.id === sel.trackId)?.clips.find((c) => c.id === sel.clipId) : null;

  const addLayer = (kind) => {
    const n = project.tracks.filter((x) => x.kind === kind).length + 1;
    const tr = { id: uid(), kind, label: `${kind === "video" ? "Video" : "Audio"} ${n}`, clips: [] };
    commit({ ...project, tracks: kind === "video" ? [tr, ...project.tracks] : [...project.tracks, tr] });
    setTrackSel(tr.id);
  };
  const removeLayer = (id) => {
    if (project.tracks.length <= 1) return;
    commit({ ...project, tracks: project.tracks.filter((x) => x.id !== id) });
    if (sel?.trackId === id) setSel(null);
    if (trackSel === id) setTrackSel(project.tracks.find((x) => x.id !== id).id);
  };

  const addFromStudio = async (v) => {
    const tr = project.tracks.find((x) => x.id === trackSel) ?? project.tracks[0];
    try {
      const d = await readDuration(v.url);
      const at = tr.clips.reduce((m, c) => Math.max(m, clipEnd(c)), 0);
      const clip = { id: uid(), itemId: v.id, name: label(v.name), start: at, in: 0, out: d, srcDur: d, mute: false };
      commit({ ...projRef.current, tracks: projRef.current.tracks.map((x) => (x.id === tr.id ? { ...x, clips: [...x.clips, clip] } : x)) });
      setSel({ trackId: tr.id, clipId: clip.id });
    } catch (e) {
      setNote({ ok: false, text: e.message || "Could not add that video." });
    }
  };

  const splitAtPlayhead = () => {
    if (!selClip) return;
    const c = selClip;
    if (!(t > c.start + MIN_CLIP && t < clipEnd(c) - MIN_CLIP)) {
      setNote({ ok: false, text: "Put the playhead inside the selected clip to split it." });
      return;
    }
    const cut = c.in + (t - c.start);
    const right = { ...c, id: uid(), start: t, in: cut };
    commit(mapClips((tr) => (tr.id === sel.trackId ? tr.clips.flatMap((x) => (x.id === c.id ? [{ ...x, out: cut }, right] : [x])) : tr.clips)));
    setSel({ trackId: sel.trackId, clipId: right.id });
    setNote(null);
  };
  const deleteSel = () => {
    if (!selClip) return;
    commit(mapClips((tr) => (tr.id === sel.trackId ? tr.clips.filter((x) => x.id !== selClip.id) : tr.clips)));
    setSel(null);
  };
  const toggleMute = () => {
    if (!selClip) return;
    commit(mapClips((tr) => (tr.id === sel.trackId ? tr.clips.map((x) => (x.id === selClip.id ? { ...x, mute: !x.mute } : x)) : tr.clips)));
  };

  /* ---------- snapping ---------- */
  const snapTo = (value, skipId) => {
    const pts = [0, tRef.current];
    for (const tr of projRef.current.tracks) for (const c of tr.clips) if (c.id !== skipId) pts.push(c.start, clipEnd(c));
    const tol = 8 / ppsRef.current;
    let best = value, bd = tol;
    for (const p of pts) { const d = Math.abs(p - value); if (d < bd) { bd = d; best = p; } }
    return best;
  };

  /* ---------- dragging clips and their edges ---------- */
  const startGesture = (kind, tr, c) => (e) => {
    if (e.button !== 0) return;
    e.stopPropagation();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    setSel({ trackId: tr.id, clipId: c.id });
    setTrackSel(tr.id);
    gesture.current = { kind, trackId: tr.id, clipId: c.id, x0: e.clientX, orig: { ...c }, base: projRef.current, moved: false };
  };
  const moveGesture = (e) => {
    const g = gesture.current;
    if (!g) return;
    const dx = (e.clientX - g.x0) / ppsRef.current;
    if (!g.moved && Math.abs(e.clientX - g.x0) < 3) return;
    g.moved = true;
    const o = g.orig;
    const base = g.base;
    const home = base.tracks.find((x) => x.id === g.trackId);
    const others = home.clips.filter((x) => x.id !== o.id);
    const oEnd = o.start + (o.out - o.in);
    const lo = others.filter((x) => clipEnd(x) <= o.start + 1e-6).reduce((m, x) => Math.max(m, clipEnd(x)), 0);
    const hi = others.filter((x) => x.start >= oEnd - 1e-6).reduce((m, x) => Math.min(m, x.start), Infinity);
    let next = base;

    if (g.kind === "left") {
      let ns = snapTo(o.start + dx, o.id);
      ns = clamp(ns, Math.max(lo, o.start - o.in), oEnd - MIN_CLIP);
      const shift = ns - o.start;
      next = {
        ...base, tracks: base.tracks.map((tr) => (tr.id !== g.trackId ? tr
          : { ...tr, clips: tr.clips.map((x) => (x.id === o.id ? { ...x, start: ns, in: o.in + shift } : x)) })),
      };
    } else if (g.kind === "right") {
      let ne = snapTo(oEnd + dx, o.id);
      ne = clamp(ne, o.start + MIN_CLIP, Math.min(hi, o.start + (o.srcDur - o.in)));
      next = {
        ...base, tracks: base.tracks.map((tr) => (tr.id !== g.trackId ? tr
          : { ...tr, clips: tr.clips.map((x) => (x.id === o.id ? { ...x, out: o.in + (ne - o.start) } : x)) })),
      };
    } else {
      const len = o.out - o.in;
      let ns = o.start + dx;
      const a = snapTo(ns, o.id), b = snapTo(ns + len, o.id) - len;
      ns = Math.abs(a - ns) <= Math.abs(b - ns) ? a : b;
      ns = Math.max(0, ns);
      // Which layer is the pointer over? (same kind only)
      let target = home;
      for (const tr of base.tracks) {
        const el = rowEls.current[tr.id];
        if (!el) continue;
        const r = el.getBoundingClientRect();
        if (e.clientY >= r.top && e.clientY < r.bottom && tr.kind === home.kind) target = tr;
      }
      if (target.id !== home.id) {
        const clash = target.clips.some((x) => ns < clipEnd(x) - 1e-6 && ns + len > x.start + 1e-6);
        if (!clash) {
          next = {
            ...base, tracks: base.tracks.map((tr) => {
              if (tr.id === home.id) return { ...tr, clips: tr.clips.filter((x) => x.id !== o.id) };
              if (tr.id === target.id) return { ...tr, clips: [...tr.clips, { ...o, start: ns }] };
              return tr;
            }),
          };
          g.trackId = target.id;      // the clip now lives here for the rest of the drag
        }
      }
      if (next === base) {
        const nsC = clamp(ns, lo, Math.max(lo, hi - len));
        next = { ...base, tracks: base.tracks.map((tr) => (tr.id !== g.trackId ? tr
          : { ...tr, clips: tr.clips.map((x) => (x.id === o.id ? { ...x, start: nsC } : x)) })) };
      }
    }
    setProject(next);
    setSel({ trackId: g.trackId, clipId: o.id });
  };
  const endGesture = () => {
    const g = gesture.current;
    gesture.current = null;
    if (g?.moved) {
      setPast((p) => [...p.slice(-60), g.base]);
      setFuture([]);
      setDirty(true);
    }
  };

  /* ---------- the playhead ---------- */
  const seekFromEvent = (e) => {
    const sc = scrollRef.current;
    if (!sc) return;
    const r = sc.getBoundingClientRect();
    const x = e.clientX - r.left + sc.scrollLeft;
    setT(clamp(x / ppsRef.current, 0, Math.max(total, 0)));
  };
  const rulerDown = (e) => {
    e.currentTarget.setPointerCapture?.(e.pointerId);
    setPlaying(false);
    seekFromEvent(e);
    gesture.current = { kind: "seek" };
  };
  const rulerMove = (e) => { if (gesture.current?.kind === "seek") seekFromEvent(e); };
  const rulerUp = () => { if (gesture.current?.kind === "seek") gesture.current = null; };

  /* ---------- playing: one clock, and every layer's <video> follows it ---------- */
  const activeAt = (tr, time) => tr.clips.find((c) => time >= c.start - 1e-6 && time < clipEnd(c) - 1e-6);

  const syncPreview = useCallback((time, isPlaying) => {
    const p = projRef.current;
    if (!p) return;
    for (const tr of p.tracks) {
      const el = vidEls.current[tr.id];
      if (!el) continue;
      const c = activeAt(tr, time);
      if (!c) {
        if (!el.paused) el.pause();
        if (tr.kind === "video") el.style.visibility = "hidden";
        continue;
      }
      const it = byId[c.itemId];
      if (!it) continue;
      if (el.dataset.clip !== c.id || el.dataset.url !== it.url) {
        el.dataset.clip = c.id; el.dataset.url = it.url;
        el.src = it.url;
      }
      el.muted = !!c.mute;
      if (tr.kind === "video") el.style.visibility = "visible";
      const want = c.in + (time - c.start);
      if (!isPlaying) {
        if (!el.paused) el.pause();
        if (Math.abs(el.currentTime - want) > 0.04) { try { el.currentTime = want; } catch { /* not ready yet */ } }
      } else {
        if (Math.abs(el.currentTime - want) > 0.35) { try { el.currentTime = want; } catch { /* not ready yet */ } }
        if (el.paused) el.play().catch(() => {});
      }
    }
  }, [byId]);

  // paused: follow edits and seeks
  useEffect(() => { if (!playing) syncPreview(t, false); }, [t, playing, project, syncPreview]);

  useEffect(() => {
    if (!playing) {
      cancelAnimationFrame(raf.current);
      for (const el of Object.values(vidEls.current)) { try { el.pause(); } catch { /* gone */ } }
      return;
    }
    clock.current.last = performance.now();
    const tick = (now) => {
      const dt = (now - clock.current.last) / 1000;
      clock.current.last = now;
      let nt = tRef.current + dt;
      const end = projRef.current ? projectDuration(projRef.current) : 0;
      if (nt >= end) { setT(end); setPlaying(false); return; }
      tRef.current = nt;
      setT(nt);
      syncPreview(nt, true);
      const sc = scrollRef.current;
      if (sc) {
        const x = nt * ppsRef.current;
        if (x > sc.scrollLeft + sc.clientWidth - 30 || x < sc.scrollLeft) sc.scrollLeft = Math.max(0, x - 60);
      }
      raf.current = requestAnimationFrame(tick);
    };
    raf.current = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf.current);
  }, [playing, syncPreview]);

  const togglePlay = () => {
    if (!project || total <= 0) return;
    if (!playing && t >= total - 0.05) { setT(0); tRef.current = 0; }
    setPlaying((p) => !p);
  };

  /* ---------- keyboard ---------- */
  useEffect(() => {
    const onKey = (e) => {
      const tag = (e.target?.tagName || "").toLowerCase();
      if (tag === "input" || tag === "textarea") return;
      if (exp) return;
      if (e.code === "Space") { e.preventDefault(); togglePlay(); }
      else if (e.key === "Delete" || e.key === "Backspace") { e.preventDefault(); deleteSel(); }
      else if (e.key === "s" || e.key === "S") { if (!e.ctrlKey && !e.metaKey) splitAtPlayhead(); }
      else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") { e.preventDefault(); e.shiftKey ? redo() : undo(); }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });

  /* ---------- saved (unfinished) edits ---------- */
  const flash = (ok, text) => setNote({ ok, text });
  const saveEdit = async () => {
    try {
      const r = await saveStudioProject({ id: projectId, name: pname, data: { tracks: project.tracks } });
      setProjectId(r.project.id);
      setDirty(false);
      flash(true, "Saved. Open it again any time from \"saved edits\".");
      if (projects) openList();
    } catch (e) { flash(false, e.message || "Could not save this edit."); }
  };
  const openList = async () => {
    try { setProjects((await listStudioProjects()).projects); }
    catch (e) { flash(false, e.message || "Could not open your saved edits."); }
  };
  const loadEdit = async (id) => {
    try {
      const r = (await getStudioProject(id)).project;
      let gone = 0;
      const tracks = (r.data?.tracks ?? []).map((tr) => ({
        ...tr, clips: tr.clips.filter((c) => { const ok = !!byId[c.itemId]; if (!ok) gone++; return ok; }),
      }));
      if (!tracks.length) throw new Error("That saved edit is empty.");
      setPast([]); setFuture([]); setProject({ tracks }); setPname(r.name); setProjectId(r.id);
      setDirty(false); setSel(null); setT(0); setPlaying(false); setTrackSel(tracks[0].id);
      setProjects(null);
      flash(!gone, gone ? `Opened. ${gone} clip${gone > 1 ? "s were" : " was"} left out because the video is no longer in your Studio.` : "Opened.");
    } catch (e) { flash(false, e.message || "Could not open that saved edit."); }
  };
  const removeEdit = async (id) => {
    try { await deleteStudioProject(id); if (id === projectId) setProjectId(""); await openList(); }
    catch (e) { flash(false, e.message || "Could not delete that saved edit."); }
  };

  /* ---------- rendering ---------- */
  const startExport = async (mode = "new") => {
    setPlaying(false);
    const started = Date.now();
    setExp({ phase: "run", status: "Starting…", progress: 0, started, elapsed: 0 });
    const getFile = async (id) => {
      if (!fileCache.current.has(id)) fileCache.current.set(id, await fetchStudioVideo(id));
      return fileCache.current.get(id).slice();         // ffmpeg takes ownership of what it is given
    };
    try {
      const out = await renderProject(project, {
        getFile,
        onStatus: (status) => setExp((x) => (x && x.phase === "run" ? { ...x, status } : x)),
        onProgress: (progress) => setExp((x) => (x && x.phase === "run" ? { ...x, progress } : x)),
      });
      const url = URL.createObjectURL(new Blob([out], { type: "video/mp4" }));
      setExp((x) => (x ? { phase: "done", mode, bytes: out, url, started, elapsed: x.elapsed, mb: out.length / 1048576, saving: true } : x));
      await saveResult(mode === "replace", out);
    } catch (e) {
      setExp((x) => (x ? { phase: "error", text: e.message || "The video could not be rendered.", elapsed: x.elapsed } : x));
    }
  };
  useEffect(() => {
    if (!exp || exp.phase !== "run") return;
    const id = setInterval(() => setExp((x) => (x && x.phase === "run" ? { ...x, elapsed: Math.round((Date.now() - x.started) / 1000) } : x)), 500);
    return () => clearInterval(id);
  }, [exp?.phase]);
  const closeExport = () => {
    if (exp?.phase === "run") cancelRender();
    if (exp?.url) URL.revokeObjectURL(exp.url);
    setExp(null);
  };
  const saveResult = async (replace, bytes) => {
    setExp((x) => ({ ...x, saving: true, saveErr: null }));
    try {
      const data = bytes ?? exp.bytes;
      await putStudioVideo(replace ? { bytes: data, replaceId: item.id } : { bytes: data, name: pname });
      await onSaved?.();
      if (replace) { closeExport(); onBack(); return; }
      setExp((x) => ({ ...x, saving: false, saved: true }));
    } catch (e) {
      setExp((x) => ({ ...x, saving: false, saveErr: e.message || "Could not save." }));
    }
  };

  /* ---------- drawing ---------- */
  const link = (color, off) => ({ background: "none", border: "none", padding: 0, fontFamily: T.mono, fontSize: 11.5,
    color: off ? T.boneDim + "66" : color, cursor: off ? "default" : "pointer" });
  const chip = (on) => ({ padding: "5px 10px", borderRadius: 2, cursor: "pointer", background: "transparent",
    fontFamily: T.mono, fontSize: 11, color: on ? T.bone : T.boneDim, border: `1px solid ${on ? T.ochre : T.edge}` });

  if (narrow) {
    return (
      <div>
        <button className="pf-btn" onClick={onBack} style={link(T.boneDim, false)}>← back to studio</button>
        <p style={{ fontFamily: T.serif, fontSize: 14.5, color: T.boneDim, lineHeight: 1.6 }}>
          The video editor needs a wider screen for now. Open this page on a computer to edit videos.
        </p>
      </div>
    );
  }

  const back = () => { if (dirty) setLeaving(true); else onBack(); };

  const W = Math.max(total + 12, 30) * pps;
  const tickStep = [0.5, 1, 2, 5, 10, 15, 30, 60].find((s) => s * pps >= 70) ?? 60;
  const ticks = [];
  for (let s = 0; s * pps <= W; s += tickStep) ticks.push(s);
  const tracks = project?.tracks ?? [];

  return (
    <div>
      <style>{CSS}</style>

      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "baseline", gap: 14, marginBottom: 12 }}>
        <button className="pf-btn" onClick={back} style={link(T.boneDim, false)}>← back to studio</button>
        <input value={pname} onChange={(e) => { setPname(e.target.value.slice(0, 60)); setDirty(true); }} aria-label="Edit name"
          style={{ background: "transparent", border: "none", borderBottom: `1px solid ${T.edge}`, color: T.bone, fontFamily: T.serif, fontSize: 18, padding: "0 2px", minWidth: 220 }} />
        <span style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>video editor</span>
        {leaving && (
          <span style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay }}>
            Leave without saving this edit?{" "}
            <button className="pf-btn" onClick={onBack} style={link(T.clay, false)}>yes, leave</button>{" · "}
            <button className="pf-btn" onClick={() => setLeaving(false)} style={link(T.boneDim, false)}>stay</button>
          </span>
        )}
      </div>

      {loadErr && <div style={{ fontFamily: T.mono, fontSize: 12, color: "#e0786a" }}>{loadErr}</div>}
      {!project && !loadErr && <div style={{ fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>opening the video…</div>}

      {project && (
        <>
          {/* the main display */}
          <div style={{ position: "relative", width: "100%", aspectRatio: "16 / 9", background: "#000", borderRadius: 2, overflow: "hidden" }}>
            {[...tracks].reverse().map((tr, i) => (
              <video key={tr.id} ref={(el) => { if (el) vidEls.current[tr.id] = el; else delete vidEls.current[tr.id]; }}
                playsInline preload="auto"
                style={tr.kind === "video"
                  ? { position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "contain", zIndex: i + 1, visibility: "hidden" }
                  : { display: "none" }} />
            ))}
            {total <= 0 && (
              <div style={{ position: "absolute", inset: 0, display: "grid", placeItems: "center", fontFamily: T.mono, fontSize: 12, color: T.boneDim }}>
                Add a video from your Studio below.
              </div>
            )}
          </div>

          {/* transport */}
          <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: 14, margin: "12px 0 8px" }}>
            <button className="pf-btn" onClick={togglePlay} style={chip(true)}>{playing ? "❚❚ pause" : "▶ play"}</button>
            <span style={{ fontFamily: T.mono, fontSize: 12, color: T.bone, minWidth: 120 }}>{fmt(t)} / {fmt(total)}</span>
            <button className="pf-btn" onClick={splitAtPlayhead} disabled={!selClip} style={link(T.bone, !selClip)}>split (S)</button>
            <button className="pf-btn" onClick={toggleMute} disabled={!selClip} style={link(T.bone, !selClip)}>{selClip?.mute ? "unmute clip" : "mute clip"}</button>
            <button className="pf-btn" onClick={deleteSel} disabled={!selClip} style={link(T.clay, !selClip)}>delete</button>
            <button className="pf-btn" onClick={undo} disabled={!past.length} style={link(T.bone, !past.length)}>undo</button>
            <button className="pf-btn" onClick={redo} disabled={!future.length} style={link(T.bone, !future.length)}>redo</button>
            <span style={{ flex: 1 }} />
            <span style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>zoom</span>
            <button className="pf-btn" onClick={() => setPps((p) => clamp(Math.round(p / 1.5), 6, 240))} style={chip(false)}>−</button>
            <button className="pf-btn" onClick={() => setPps((p) => clamp(Math.round(p * 1.5), 6, 240))} style={chip(false)}>+</button>
          </div>

          {/* the timeline */}
          <div style={{ display: "flex", border: `1px solid ${T.edge}`, borderRadius: 2, background: "rgba(0,0,0,0.18)" }}>
            <div style={{ width: LABEL_W, flexShrink: 0, borderRight: `1px solid ${T.edge}` }}>
              <div style={{ height: RULER_H }} />
              {tracks.map((tr) => (
                <div key={tr.id} onClick={() => setTrackSel(tr.id)}
                  style={{ height: ROW_H, boxSizing: "border-box", padding: "4px 8px", cursor: "pointer", borderTop: `1px solid ${T.edge}`,
                    background: trackSel === tr.id ? T.ochre + "22" : "transparent" }}>
                  <div style={{ fontFamily: T.mono, fontSize: 11, color: trackSel === tr.id ? T.bone : T.boneDim }}>{tr.label}</div>
                  {tracks.length > 1 && (
                    <button className="pf-btn" onClick={(e) => { e.stopPropagation(); removeLayer(tr.id); }} style={{ ...link(T.boneDim, false), fontSize: 10 }}>remove</button>
                  )}
                </div>
              ))}
            </div>

            <div ref={scrollRef} style={{ flex: 1, overflowX: "auto", overflowY: "hidden", position: "relative", userSelect: "none" }}
              onPointerDown={(e) => { if (e.target === e.currentTarget) setSel(null); }}>
              <div style={{ width: W, position: "relative" }} onPointerDown={(e) => { if (e.target === e.currentTarget) setSel(null); }}>
                <div onPointerDown={rulerDown} onPointerMove={rulerMove} onPointerUp={rulerUp} onPointerCancel={rulerUp}
                  style={{ height: RULER_H, position: "relative", cursor: "pointer", touchAction: "none" }}>
                  {ticks.map((s) => (
                    <div key={s} style={{ position: "absolute", left: s * pps, top: 0, height: "100%", borderLeft: `1px solid ${T.edge}`,
                      paddingLeft: 4, fontFamily: T.mono, fontSize: 10, color: T.boneDim, lineHeight: `${RULER_H}px`, pointerEvents: "none" }}>
                      {fmtClock(s)}
                    </div>
                  ))}
                </div>

                {tracks.map((tr) => (
                  <div key={tr.id} ref={(el) => { if (el) rowEls.current[tr.id] = el; else delete rowEls.current[tr.id]; }}
                    onPointerDown={(e) => { if (e.target === e.currentTarget) { setSel(null); setTrackSel(tr.id); } }}
                    style={{ height: ROW_H, boxSizing: "border-box", borderTop: `1px solid ${T.edge}`, position: "relative" }}>
                    {tr.clips.map((c) => {
                      const on = sel?.clipId === c.id;
                      const col = tr.kind === "video" ? T.ochre : T.moss;
                      return (
                        <div key={c.id} className="sve-clip" onPointerDown={startGesture("move", tr, c)} onPointerMove={moveGesture}
                          onPointerUp={endGesture} onPointerCancel={endGesture}
                          title={`${c.name} · ${fmt(clipLength(c))}`}
                          style={{ position: "absolute", left: c.start * pps, width: Math.max(4, clipLength(c) * pps), top: 3, bottom: 3, boxSizing: "border-box",
                            background: col + (c.mute ? "22" : "55"), border: `1px solid ${on ? T.bone : col}`, borderRadius: 2, cursor: "grab",
                            overflow: "hidden", touchAction: "none" }}>
                          <div style={{ padding: "3px 10px", fontFamily: T.mono, fontSize: 10.5, color: T.bone, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", pointerEvents: "none" }}>
                            {c.mute ? "🔇 " : ""}{c.name}
                          </div>
                          {["left", "right"].map((side) => (
                            <div key={side} onPointerDown={startGesture(side, tr, c)} onPointerMove={moveGesture} onPointerUp={endGesture} onPointerCancel={endGesture}
                              style={{ position: "absolute", top: 0, bottom: 0, [side]: 0, width: 8, cursor: "ew-resize", background: on ? T.bone + "99" : col + "99", touchAction: "none" }} />
                          ))}
                        </div>
                      );
                    })}
                  </div>
                ))}

                <div style={{ position: "absolute", left: t * pps, top: 0, bottom: 0, width: 0, borderLeft: `2px solid ${T.clay}`, pointerEvents: "none", zIndex: 5 }} />
              </div>
            </div>
          </div>

          <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: 16, marginTop: 10 }}>
            <button className="pf-btn" onClick={() => addLayer("video")} style={link(T.boneDim, false)}>+ video layer</button>
            <button className="pf-btn" onClick={() => addLayer("audio")} style={link(T.boneDim, false)}>+ audio layer</button>
            <span style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim }}>
              Drag a clip to move it, drag its ends to trim. Higher layers show on top. Click a layer name to choose where "add" puts a video.
            </span>
          </div>

          {/* media bin */}
          <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, margin: "18px 0 8px" }}>
            Your Studio videos · click one to add it to {tracks.find((x) => x.id === trackSel)?.label ?? "the timeline"}
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 10 }}>
            {videos.map((v) => (
              <button key={v.id} type="button" onClick={() => addFromStudio(v)} title={`Add ${label(v.name)}`}
                style={{ background: "none", border: `1px solid ${T.edge}`, borderRadius: 3, padding: 3, cursor: "pointer", width: 132 }}>
                <video src={v.url + "#t=0.1"} muted playsInline preload="metadata"
                  style={{ width: "100%", aspectRatio: "16 / 9", objectFit: "cover", display: "block", background: "#000", borderRadius: 1 }} />
                <div style={{ fontFamily: T.mono, fontSize: 10, color: T.boneDim, marginTop: 3, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", textAlign: "left" }}>
                  {label(v.name)}
                </div>
              </button>
            ))}
          </div>

          {/* saving and rendering */}
          <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: 20, marginTop: 20 }}>
            <button className="pf-btn" onClick={() => startExport("new")} disabled={total <= 0 || tooLong} style={{ ...link(T.moss, total <= 0 || tooLong), fontSize: 12.5 }}>
              save as new video · free
            </button>
            {byId[item.id] && (askReplace
              ? <span style={{ fontFamily: T.mono, fontSize: 11.5, color: T.clay }}>
                  This overwrites the original video.{" "}
                  <button className="pf-btn" onClick={() => { setAskReplace(false); startExport("replace"); }} style={link(T.clay, false)}>yes, replace it</button>{" · "}
                  <button className="pf-btn" onClick={() => setAskReplace(false)} style={link(T.boneDim, false)}>no</button>
                </span>
              : <button className="pf-btn" onClick={() => setAskReplace(true)} disabled={total <= 0 || tooLong} style={link(T.ochre, total <= 0 || tooLong)}>
                  replace the original video
                </button>)}
            <button className="pf-btn" onClick={saveEdit} style={link(T.ochre, false)}>{projectId ? "save changes to this edit" : "save this edit for later"}</button>
            <button className="pf-btn" onClick={() => (projects ? setProjects(null) : openList())} style={link(T.boneDim, false)}>
              {projects ? "hide saved edits" : "saved edits"}
            </button>
            <span style={{ fontFamily: T.mono, fontSize: 11, color: tooLong ? "#e0786a" : T.boneDim }}>
              {tooLong ? `Too long: an edit can be at most ${MAX_EDIT_SECONDS / 60} minutes.` : `Length ${fmt(total)} of ${MAX_EDIT_SECONDS / 60}:00`}
            </span>
          </div>
          {note && (
            <div style={{ fontFamily: T.mono, fontSize: 11.5, lineHeight: 1.6, marginTop: 10, color: note.ok ? T.moss : "#e0786a" }}>{note.text}</div>
          )}
          {projects && (
            <div style={{ marginTop: 10, border: `1px solid ${T.edge}`, borderRadius: 2, padding: 10 }}>
              {projects.length === 0 && <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, fontStyle: "italic" }}>No saved edits yet.</div>}
              {projects.map((p) => (
                <div key={p.id} style={{ display: "flex", gap: 16, alignItems: "baseline", padding: "3px 0" }}>
                  <span style={{ fontFamily: T.serif, fontSize: 14, minWidth: 220 }}>{label(p.name)}</span>
                  <span style={{ fontFamily: T.mono, fontSize: 10.5, color: T.boneDim }}>{new Date(p.updatedAt).toLocaleString()}</span>
                  <button className="pf-btn" onClick={() => loadEdit(p.id)} style={link(T.moss, false)}>open</button>
                  <button className="pf-btn" onClick={() => removeEdit(p.id)} style={link(T.clay, false)}>delete</button>
                </div>
              ))}
            </div>
          )}
        </>
      )}

      {/* the render overlay */}
      {exp && (
        <div style={{ position: "fixed", inset: 0, zIndex: 1000, background: "rgba(0,0,0,0.78)", display: "grid", placeItems: "center", padding: 20 }}>
          <div style={{ width: "min(640px, 100%)", background: "#14110f", border: `1px solid ${T.edge}`, borderRadius: 3, padding: 22 }}>
            {exp.phase === "run" && (
              <>
                <div style={{ fontFamily: T.serif, fontSize: 18, marginBottom: 6 }}>Making your video</div>
                <div style={{ fontFamily: T.mono, fontSize: 34, color: T.bone, letterSpacing: 1 }}>{fmtClock(exp.elapsed)}</div>
                <div style={{ position: "relative", height: 8, margin: "14px 0 10px", background: T.edge, borderRadius: 4, overflow: "hidden" }}>
                  <div style={{ position: "absolute", inset: 0, width: `${Math.round(exp.progress * 100)}%`, background: T.ochre, transition: "width .4s" }} />
                  <div style={{ position: "absolute", top: 0, bottom: 0, width: "30%", background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.35), transparent)", animation: "sve-sweep 1.6s linear infinite" }} />
                </div>
                <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, animation: "sve-pulse 2s ease-in-out infinite" }}>
                  {exp.status}{exp.progress > 0 ? ` · ${Math.round(exp.progress * 100)}%` : ""}
                </div>
                <div style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim, lineHeight: 1.6, marginTop: 10 }}>
                  The video is put together on your computer, so it costs nothing, and it is saved to your Studio when it is done. A one-minute edit can take one to three minutes. Keep this page open; the timer shows it is still working.
                </div>
                <div style={{ marginTop: 14 }}>
                  <button className="pf-btn" onClick={closeExport} style={link(T.clay, false)}>cancel</button>
                </div>
              </>
            )}
            {exp.phase === "error" && (
              <>
                <div style={{ fontFamily: T.serif, fontSize: 18, marginBottom: 8 }}>It did not work</div>
                <div style={{ fontFamily: T.mono, fontSize: 12, color: "#e0786a", lineHeight: 1.6 }}>{exp.text}</div>
                <div style={{ marginTop: 14 }}>
                  <button className="pf-btn" onClick={closeExport} style={link(T.boneDim, false)}>close</button>
                </div>
              </>
            )}
            {exp.phase === "done" && (
              <>
                <div style={{ fontFamily: T.serif, fontSize: 18, marginBottom: 8 }}>
                  Ready in {fmtClock(exp.elapsed)} · {exp.mb.toFixed(1)} MB
                </div>
                <video src={exp.url} controls playsInline style={{ width: "100%", aspectRatio: "16 / 9", background: "#000", borderRadius: 2 }} />
                {exp.saving && <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.boneDim, marginTop: 12, animation: "sve-pulse 2s ease-in-out infinite" }}>Saving to your Studio…</div>}
                {exp.saved && <div style={{ fontFamily: T.mono, fontSize: 11.5, color: T.moss, marginTop: 12 }}>Saved as a new video in your Studio.</div>}
                {!exp.saving && !exp.saved && (
                  <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: 18, marginTop: 14 }}>
                    <button className="pf-btn" onClick={() => saveResult(exp.mode === "replace")} style={link(T.moss, false)}>try saving again</button>
                    <span style={{ fontFamily: T.mono, fontSize: 11, color: T.boneDim }}>The finished video is kept here, so nothing needs to be rendered again.</span>
                  </div>
                )}
                {!exp.saving && (
                  <div style={{ marginTop: 10 }}>
                    <a href={exp.url} download={`${label(pname)}.mp4`} style={{ ...link(T.boneDim, false), textDecoration: "none" }}>download</a>
                  </div>
                )}
                {exp.saveErr && <div style={{ fontFamily: T.mono, fontSize: 11.5, color: "#e0786a", marginTop: 10 }}>{exp.saveErr}</div>}
                <div style={{ marginTop: 14 }}>
                  <button className="pf-btn" onClick={closeExport} style={link(T.boneDim, false)}>close</button>
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}
